'use client';

import dynamic from 'next/dynamic';
import Link from 'next/link';
import ProtectedRoute from '@/components/auth/ProtectedRoute';
import { useNewInterview } from '@/hooks/useNewInterview';
import { UploadStep } from '@/components/features/interview/NewInterview/UploadStep';
import { ActiveSessionsPanel } from '@/components/features/interview/NewInterview/ActiveSessionsPanel';
import { MatchingResultPanel } from '@/components/features/interview/NewInterview/MatchingResultPanel';
import { Button } from '@/components/ui/button';
import { CheckCircle, AlertTriangle, AlertCircle, X } from 'lucide-react';

const PdfViewerModal = dynamic(() => import('@/components/common/PdfViewerModal'), { ssr: false });

export default function NewInterviewPage() {
  const {
    user,
    cvFile, setCvFile, jdFile, setJdFile, jdText, setJdText,
    cvSource, setCvSource, jdSource, setJdSource,
    savedResumes, savedJds,
    selectedResumeId, setSelectedResumeId,
    selectedJdId, setSelectedJdId,
    dragOverCv, dragOverJd,
    handleDragOver, handleDragLeave, handleDrop, handleFileChange, triggerFileSelect,
    fileInputCvRef, fileInputJdRef,
    cvError, jdError, uploading, analyzing, generating, uploadProgress, apiError,
    sessionId, roleTitle, ingested, assessment, activeSessions, isCloning,
    keywordMetadata, rawCvText, rawJdText,
    cvDisplayName, jdDisplayName,
    criteriaFilter, setCriteriaFilter,
    activeView, setActiveView,
    viewerOpen, setViewerOpen, viewerUrl, setViewerUrl, viewerTitle, setViewerTitle,
    handleUploadAndIngest, handleRunAssessment,
    handleResumeSession, handleRestart, handleViewAssessment, handleReset, handleContinueToSelection,
  } = useNewInterview();

  return (
    <ProtectedRoute>
      <div className="min-h-screen bg-gradient-to-br from-brand-orange/5 via-background to-brand-green/5 text-foreground flex flex-col font-sans">
        <main className="max-w-5xl w-full mx-auto px-4 py-12 flex-1 flex flex-col justify-center">
          {}
          <div className="mb-10 text-center space-y-2">
            <h1 className="text-3xl font-extrabold tracking-tight sm:text-4xl text-foreground">
              Khởi tạo phỏng vấn
            </h1>
            <p className="text-sm text-muted-foreground max-w-xl mx-auto">
              Tải lên CV và Mô tả công việc (JD) để AI phân tích mức độ tương thích
            </p>
          </div>

          {}
          {!assessment && !uploading && !analyzing && (
            <ActiveSessionsPanel
              sessions={activeSessions}
              cloningId={isCloning}
              onResume={handleResumeSession}
              onRestart={handleRestart}
              onViewAssessment={handleViewAssessment}
            />
          )}

          {}
          {apiError && (
            <div className="mb-6 flex items-center justify-between gap-4 p-4 rounded-xl border border-destructive/20 bg-destructive/10 text-destructive text-sm animate-fade-up">
              <span className="flex items-center gap-2 font-medium">
                <AlertTriangle size={16} />
                {apiError}
              </span>
              <Button size="sm" variant="ghost" onClick={handleReset} className="hover:bg-destructive/20 text-destructive">
                Thử lại
              </Button>
            </div>
          )}

          {}
          {!uploading && !analyzing && !assessment && !ingested && (
            <div className="bg-card border border-border rounded-2xl p-6 md:p-8 shadow-xl animate-fade-up">
              <UploadStep
                cvSource={cvSource} setCvSource={setCvSource}
                jdSource={jdSource} setJdSource={setJdSource}
                cvFile={cvFile} jdFile={jdFile}
                jdText={jdText} setJdText={setJdText}
                dragOverCv={dragOverCv} dragOverJd={dragOverJd}
                cvError={cvError} jdError={jdError}
                savedResumes={savedResumes} savedJds={savedJds}
                selectedResumeId={selectedResumeId} setSelectedResumeId={setSelectedResumeId}
                selectedJdId={selectedJdId} setSelectedJdId={setSelectedJdId}
                fileInputCvRef={fileInputCvRef} fileInputJdRef={fileInputJdRef}
                defaultResumeId={user?.defaultResumeId || null}
                onDragOver={handleDragOver} onDragLeave={handleDragLeave} onDrop={handleDrop}
                onFileChange={handleFileChange} onTrigger={triggerFileSelect}
                onClearCv={() => setCvFile(null)} onClearJd={() => setJdFile(null)}
                onViewPdf={(url, title) => { setViewerUrl(url); setViewerTitle(title); setViewerOpen(true); }}
                onSubmit={handleUploadAndIngest}
                disabled={
                  (cvSource === 'upload' && !cvFile) ||
                  ((cvSource === 'saved' || cvSource === 'default') && !selectedResumeId) ||
                  (jdSource === 'upload' && !jdFile) ||
                  (jdSource === 'text' && !jdText.trim()) ||
                  (jdSource === 'saved' && !selectedJdId)
                }
              />
            </div>
          )}

          {}
          {uploading && (
            <div className="bg-card border border-border rounded-2xl p-12 shadow-xl flex flex-col items-center justify-center gap-6 text-center animate-fade-up">
              <div className="size-10 rounded-full border-4 border-t-brand-orange border-muted animate-spin" />
              <div className="space-y-1">
                <h3 className="text-lg font-bold text-foreground">Đang tải tài liệu lên...</h3>
                <p className="text-xs text-muted-foreground">Hồ sơ của bạn đang được truyền tải an toàn</p>
              </div>
              <div className="w-64 h-1.5 bg-muted rounded-full overflow-hidden">
                <div className="h-full bg-brand-orange transition-all duration-300" style={{ width: `${uploadProgress}%` }} />
              </div>
            </div>
          )}

          {}
          {analyzing && (
            <div className="bg-card border border-border rounded-2xl p-12 shadow-xl flex flex-col items-center justify-center gap-6 text-center animate-fade-up">
              <div className="size-10 rounded-full border-4 border-t-purple-500 border-muted animate-spin" />
              <div className="space-y-1">
                <h3 className="text-lg font-bold text-foreground">AI đang xử lý tài liệu của bạn...</h3>
                <p className="text-xs text-muted-foreground">Quá trình này có thể mất tới 10-35 giây đối với tài liệu mới</p>
              </div>
              <div className="text-xs text-muted-foreground/80 space-y-1 pt-2">
                {!ingested ? (
                  <>
                    <p>✓ Trích xuất nội dung văn bản từ PDF...</p>
                    <p className="font-semibold text-purple-600 animate-pulse">➜ Chuẩn hóa định dạng tài liệu...</p>
                  </>
                ) : (
                  <p className="font-semibold text-purple-600 animate-pulse">➜ Đối chiếu và chấm điểm mức độ tương thích kỹ năng...</p>
                )}
              </div>
            </div>
          )}

          {}
          {ingested && !analyzing && !assessment && (
            <div className="bg-card border border-border rounded-2xl p-10 shadow-xl text-center space-y-6 animate-fade-up">
              <span className="flex size-14 items-center justify-center rounded-full bg-emerald-100 text-emerald-600 mx-auto">
                <CheckCircle size={32} />
              </span>
              <div className="space-y-1">
                <h2 className="text-xl font-bold text-foreground">Tải lên thành công!</h2>
                <p className="text-sm text-muted-foreground max-w-md mx-auto">
                  Tài liệu của bạn đã được chuẩn hóa và lưu trữ. Hệ thống đã sẵn sàng để phân tích độ tương thích.
                </p>
              </div>
              <div className="flex justify-center gap-3 pt-2">
                <Button variant="outline" onClick={handleReset}>
                  Tải lại tài liệu khác
                </Button>
                <Button onClick={() => handleRunAssessment(false)} className="bg-brand-orange text-white hover:bg-brand-orange-hover">
                  Tiến hành Đánh giá (Assessment)
                </Button>
              </div>
            </div>
          )}

          {}
          {assessment && (
            <div className="bg-card border border-border rounded-2xl p-6 md:p-8 shadow-xl animate-fade-up">
              <MatchingResultPanel
                assessment={assessment}
                roleTitle={roleTitle}
                analyzing={analyzing}
                generating={generating}
                rawCvText={rawCvText}
                rawJdText={rawJdText}
                cvDisplayName={cvDisplayName}
                jdDisplayName={jdDisplayName}
                keywordMetadata={keywordMetadata}
                criteriaFilter={criteriaFilter}
                activeView={activeView}
                onCriteriaFilter={setCriteriaFilter}
                onActiveView={setActiveView}
                onRefreshAssessment={() => handleRunAssessment(true)}
                onReset={handleReset}
                onContinue={handleContinueToSelection}
              />
            </div>
          )}

          {}
          {generating && (
            <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-card border border-border rounded-2xl p-8 max-w-sm w-full text-center space-y-4 shadow-2xl">
                <div className="size-10 rounded-full border-4 border-t-amber-500 border-muted animate-spin mx-auto" />
                <h3 className="text-lg font-bold text-foreground">Đang thiết lập phòng phỏng vấn...</h3>
                <p className="text-xs text-muted-foreground">AI đang biên soạn ngân hàng câu hỏi cá nhân hóa cho bạn</p>
              </div>
            </div>
          )}
        </main>
      </div>

      {}
      {viewerOpen && (
        <PdfViewerModal
          isOpen={viewerOpen}
          onClose={() => setViewerOpen(false)}
          pdfUrl={viewerUrl}
          title={viewerTitle}
        />
      )}
    </ProtectedRoute>
  );
}

'use client';

import React, { Suspense } from 'react';
import Link from 'next/link';
import { useRouter, useSearchParams } from 'next/navigation';
import { Terminal, UserCheck, Code2, Briefcase, Network } from 'lucide-react';
import styles from './type.module.css';

interface InterviewTypeCard {
  id: string;
  name: string;
  description: string;
  icon: React.ComponentType<{ className?: string; size?: number }>;
  enabled: boolean;
}

const INTERVIEW_TYPES: InterviewTypeCard[] = [
  {
    id: 'technical',
    name: 'Phỏng vấn Kỹ thuật',
    description: 'Đánh giá kiến thức chuyên môn, tư duy thuật toán, và khả năng giải quyết các vấn đề kỹ thuật thực tế.',
    icon: Terminal,
    enabled: true,
  },
  {
    id: 'behavioural',
    name: 'Phỏng vấn Hành vi',
    description: 'Đánh giá các kỹ năng mềm, độ phù hợp văn hóa doanh nghiệp, cách giải quyết xung đột thông qua các tình huống thực tế.',
    icon: UserCheck,
    enabled: false,
  },
  {
    id: 'live-coding',
    name: 'Lập trình Trực tiếp',
    description: 'Kiểm tra kỹ năng lập trình trực tiếp, viết mã sạch, tối ưu thuật toán và cấu trúc dữ liệu dưới áp lực thời gian thực.',
    icon: Code2,
    enabled: false,
  },
  {
    id: 'case-study',
    name: 'Giải quyết Tình huống',
    description: 'Phân tích các tình huống thực tế (case study) về nghiệp vụ kinh doanh, đưa ra giải pháp toàn diện và tối ưu.',
    icon: Briefcase,
    enabled: false,
  },
  {
    id: 'system-design',
    name: 'Thiết kế Hệ thống',
    description: 'Đánh giá khả năng thiết kế kiến trúc phần mềm quy mô lớn, tính mở rộng (scalability) và khả năng chịu tải cao.',
    icon: Network,
    enabled: false,
  },
];

function TypeSelectionContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const sessionId = searchParams.get('sessionId') || `session-${Date.now()}`;

  const handleCardClick = (type: InterviewTypeCard) => {
    if (!type.enabled) return;
    router.push(`/interview/session/${sessionId}`);
  };

  return (
    <div className={styles.container}>
      <header className={styles.header}>
        <Link href="/history" className={styles.logo}>
          <img src="/logo.png" alt="Smile Interview Logo" className={styles.logoImg} />
        </Link>
        <nav className={styles.navLinks}>
          <Link href="/history" className={styles.navLink}>
            Lịch sử
          </Link>
          <Link href="/interview/new" className={styles.navLink}>
            Phỏng vấn mới
          </Link>
        </nav>
      </header>

      {/* Main Content */}
      <main className={styles.content}>
        <div className={styles.titleSection}>
          <h1>Lựa chọn loại hình phỏng vấn</h1>
          <p className={styles.subtitle}>Chọn hình thức phỏng vấn giả lập phù hợp với mục tiêu của bạn</p>
        </div>

        <div className={styles.grid}>
          {INTERVIEW_TYPES.map((type) => {
            const isEnabled = type.enabled;
            return (
              <div
                key={type.id}
                className={`${styles.card} ${isEnabled ? styles.cardEnabled : styles.cardDisabled}`}
                onClick={() => handleCardClick(type)}
              >
                <div className={styles.cardHeader}>
                  <div className={`${styles.iconWrapper} ${isEnabled ? styles.iconWrapperActive : styles.iconWrapperDisabled}`}>
                    <type.icon className={styles.iconElement} size={24} />
                  </div>
                  <span className={`${styles.badge} ${isEnabled ? styles.badgeActive : ''}`}>
                    {isEnabled ? 'Sẵn có' : 'Sắp ra mắt'}
                  </span>
                </div>
                
                <div className={styles.cardBody}>
                  <h3>{type.name}</h3>
                  <p>{type.description}</p>
                </div>

                <div className={styles.cardFooter}>
                  {isEnabled ? (
                    <span>Bắt đầu luyện tập ➔</span>
                  ) : (
                    <span>Tạm khóa</span>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        <div className={styles.actions}>
          <Link href={`/interview/new?sessionId=${sessionId}`} className={styles.backButton}>
            ➔ Quay lại tải lên CV
          </Link>
        </div>
      </main>

      <footer className={styles.footer}>
        <img src="/footer.png" alt="Smile Interview Footer" className={styles.footerImg} />
      </footer>
    </div>
  );
}

export default function InterviewTypePage() {
  return (
    <Suspense fallback={
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#f8fafc' }}>
        <p style={{ fontFamily: 'Inter, sans-serif', color: '#64748b' }}>Đang tải cấu hình...</p>
      </div>
    }>
      <TypeSelectionContent />
    </Suspense>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { useParams, useRouter } from 'next/navigation';
import { FolderOpen, Target, Briefcase, Wrench, Lightbulb, AlertTriangle, MessageSquare, BarChart3, CheckCircle2, XCircle, TrendingUp, Award, UserCheck, ShieldCheck, Brain, CheckCircle, AlertCircle } from 'lucide-react';
import { historyService, SessionHistoryItem } from '@/services/historyService';
import styles from './result.module.css';

export default function InterviewResultPage() {
  const params = useParams();
  const router = useRouter();
  const id = (params?.id as string) || '';

  const [session, setSession] = useState<SessionHistoryItem | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [expandedIndexes, setExpandedIndexes] = useState<number[]>([0]); // Open first item by default

  useEffect(() => {
    let active = true;
    let pollCount = 0;
    const maxPolls = 25; // 50 seconds max
    let timerId: NodeJS.Timeout;

    async function loadSession() {
      if (!id) return;
      try {
        const data = await historyService.getSessionById(id);
        if (!active) return;

        if (data) {
          const isEvaluated = data.status !== 'Completed' || (data.overallFeedback !== undefined && data.overallFeedback !== null && data.overallFeedback.trim() !== '');

          if (isEvaluated || pollCount >= maxPolls) {
            setSession(data);
            setLoading(false);
          } else {
            pollCount++;
            setLoading(true);
            timerId = setTimeout(loadSession, 2000);
          }
        } else {
          setSession(null);
          setLoading(false);
        }
      } catch (err) {
        console.error('Lỗi khi tải kết quả phỏng vấn:', err);
        if (active) setLoading(false);
      }
    }

    loadSession();

    return () => {
      active = false;
      if (timerId) clearTimeout(timerId);
    };
  }, [id]);

  const toggleAccordion = (index: number) => {
    setExpandedIndexes((prev) =>
      prev.includes(index) ? prev.filter((i) => i !== index) : [...prev, index]
    );
  };

  const formatDate = (dateStr: string) => {
    try {
      const date = new Date(dateStr);
      return date.toLocaleDateString('vi-VN', {
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    } catch {
      return dateStr;
    }
  };

  if (loading) {
    return (
      <div className={styles.container}>
        <div style={{ display: 'flex', minHeight: '80vh', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ width: '40px', height: '40px', border: '3px solid #f1f5f9', borderTop: '3px solid #4f46e5', borderRadius: '50%', animation: 'spin 1s linear infinite' }} />
          <p style={{ marginTop: '1rem', color: '#64748b', fontSize: '0.9rem' }}>Đang tải báo cáo đánh giá từ AI...</p>
          <style jsx>{`
            @keyframes spin {
              0% { transform: rotate(0deg); }
              100% { transform: rotate(360deg); }
            }
          `}</style>
        </div>
      </div>
    );
  }

  if (!session) {
    return (
      <div className={styles.container}>
        <div style={{ display: 'flex', minHeight: '80vh', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '2rem', textAlign: 'center' }}>
          <FolderOpen size={48} style={{ color: '#94a3b8' }} />
          <h2 style={{ fontSize: '1.25rem', marginTop: '1.25rem', fontWeight: 700 }}>Không tìm thấy kết quả phỏng vấn</h2>
          <p style={{ color: '#64748b', fontSize: '0.95rem', margin: '0.5rem 0 1.5rem 0', maxWidth: '360px' }}>
            Buổi phỏng vấn này không tồn tại hoặc dữ liệu đã bị xóa khỏi thiết bị.
          </p>
          <Link href="/history" className={styles.primaryButton}>
            Quay lại Lịch sử
          </Link>
        </div>
      </div>
    );
  }

  interface FinalReport {
    strengths: string[];
    weaknesses: string[];
    recommendations: string[];
    overall_score: number;
    overall_summary: string;
    hiring_recommendation: string;
  }

  let report: FinalReport | null = null;
  if (session.overallFeedback) {
    try {
      report = typeof session.overallFeedback === 'object'
        ? session.overallFeedback
        : JSON.parse(session.overallFeedback);
    } catch {
      report = null;
    }
  }

  let strengths = session.strongAreas || [];
  let weaknesses = session.gapAreas || [];
  let recommendations = session.actionableSuggestions || [];
  let score = 0;
  let overallFeedbackText = '';
  let hiringRecommendation = '';

  const isPostInterviewEvaluated = session.status === 'Completed' || report !== null;

  if (isPostInterviewEvaluated) {
    // 1. Post-interview report loaded
    score = session.overallScore || 0;
    overallFeedbackText = session.overallFeedback || '';
    hiringRecommendation = session.hiringRecommendation || '';

    if (report) {
      strengths = report.strengths || (report as any).strongAreas || strengths;
      weaknesses = report.weaknesses || (report as any).gapAreas || weaknesses;
      recommendations = report.recommendations || (report as any).actionableSuggestions || recommendations;
      
      const rawScore = report.overall_score !== undefined ? report.overall_score : (report as any).overallScore;
      if (rawScore !== undefined) {
        score = rawScore <= 10 ? rawScore * 10 : rawScore;
      }
      
      overallFeedbackText = report.overall_summary || (report as any).overallFeedback || overallFeedbackText;
      hiringRecommendation = report.hiring_recommendation || (report as any).hiringRecommendation || hiringRecommendation;
    }

    // Auto-calculate hiringRecommendation if it's 'N/A' or empty
    if (!hiringRecommendation || hiringRecommendation === 'N/A') {
      const numericScore = typeof score === 'number' ? score : parseInt(score) || 0;
      if (numericScore >= 90) {
        hiringRecommendation = 'Strong Hire';
      } else if (numericScore >= 70) {
        hiringRecommendation = 'Hire';
      } else if (numericScore >= 40) {
        hiringRecommendation = 'No Hire';
      } else {
        hiringRecommendation = 'Strong No Hire';
      }
    }
  } else {
    // 2. CV Evaluation report loaded
    score = session.competencyFitScore || 0;
    
    // Construct a beautiful CV match overall feedback summary
    overallFeedbackText = `Báo cáo đánh giá mức độ tương thích của hồ sơ ứng viên (CV) đối với mô tả công việc (JD).\n` +
      `• Mức độ phù hợp năng lực: ${session.matchLevel || 'N/A'}\n` +
      `• Cấp độ ứng viên phù hợp: ${session.candidateLevel || 'N/A'}\n` +
      `• Ước tính số năm kinh nghiệm: ${session.yearsOfExperienceEstimate || 'N/A'}`;
      
    hiringRecommendation = 'Đánh giá CV';
  }

  return (
    <div className={styles.container}>

      {/* Main Content */}
      <main className={styles.content}>
        <div className={styles.titleSection}>
          <h1>Kết quả đánh giá chi tiết</h1>
          <p className={styles.subtitle}>Báo cáo phân tích năng lực được tự động tạo bởi trợ lý ảo AI</p>
        </div>

        {/* ── Summary Section Card ── */}
        <section className={styles.summaryCard}>
          <div className={styles.scoreRow}>
            <div className={styles.scoreCircle}>
              <span className={styles.scoreNum}>{score <= 10 ? `${score}/10` : score}</span>
              <span className={styles.scoreLabel}>ĐIỂM SỐ</span>
            </div>

            <div className={styles.scoreText}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flexWrap: 'wrap', marginBottom: '0.5rem' }}>
                <h2 style={{ margin: 0 }}>Đánh giá chung</h2>
                {hiringRecommendation && (
                  <span style={{
                    fontSize: '0.7rem',
                    fontWeight: 850,
                    padding: '0.2rem 0.6rem',
                    borderRadius: '9999px',
                    textTransform: 'uppercase',
                    letterSpacing: '0.05em',
                    backgroundColor: hiringRecommendation.toLowerCase().includes('no') ? '#fef2f2' : (hiringRecommendation.toLowerCase().includes('hire') ? '#ecfdf5' : '#fffbeb'),
                    color: hiringRecommendation.toLowerCase().includes('no') ? '#b91c1c' : (hiringRecommendation.toLowerCase().includes('hire') ? '#047857' : '#d97706'),
                    border: `1px solid ${hiringRecommendation.toLowerCase().includes('no') ? '#fca5a5' : (hiringRecommendation.toLowerCase().includes('hire') ? '#a7f3d0' : '#fcd34d')}`
                  }}>
                    Quyết định: {hiringRecommendation}
                  </span>
                )}
              </div>
              <p>{overallFeedbackText}</p>
              <div style={{ marginTop: '0.75rem', fontSize: '0.8rem', color: '#64748b' }}>
                <span>Buổi phỏng vấn kết thúc ngày: </span>
                <strong>{formatDate(session.date)}</strong>
              </div>
            </div>
          </div>

          {/* Eligibility Card */}
          {session.eligibility && (
            <div style={{
              display: 'flex',
              flexDirection: 'column',
              gap: '0.75rem',
              padding: '1.25rem',
              backgroundColor: '#f8fafc',
              border: '1px solid #e2e8f0',
              borderRadius: '0.5rem',
              marginTop: '1.5rem',
              marginBottom: '0.5rem'
            }}>
              <span style={{ fontSize: '0.75rem', fontWeight: 700, color: '#475569', textTransform: 'uppercase', marginBottom: '0.1rem' }}>Kết quả sàng lọc hồ sơ</span>
              
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', borderBottom: '1px solid #e2e8f0', paddingBottom: '0.5rem', marginBottom: '0.1rem' }}>
                <span style={{ fontSize: '0.82rem', color: '#64748b' }}>Trạng thái:</span>
                <span style={{
                  fontSize: '0.75rem',
                  fontWeight: 700,
                  padding: '0.2rem 0.5rem',
                  borderRadius: '0.25rem',
                  backgroundColor: session.eligibility.status === 'ELIGIBLE' ? '#ecfdf5' : '#fef2f2',
                  color: session.eligibility.status === 'ELIGIBLE' ? '#047857' : '#b91c1c',
                  border: '1px solid currentColor'
                }}>
                  {session.eligibility.status === 'ELIGIBLE' ? 'ĐỦ ĐIỀU KIỆN (ELIGIBLE)' : 'CHƯA ĐỦ ĐIỀU KIỆN'}
                </span>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '0.75rem' }}>
                {(session.eligibility.gate_checks || []).map((check: any, idx: number) => {
                  const isMet = check.status === 'met' || check.status === 'MET';
                  return (
                    <div key={idx} style={{ display: 'flex', flexDirection: 'column', gap: '0.15rem', padding: '0.4rem 0.65rem', backgroundColor: '#ffffff', border: '1px solid #e2e8f0', borderRadius: '0.35rem' }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <strong style={{ fontSize: '0.78rem', color: '#0f172a' }}>{check.criteria_name}</strong>
                        <span style={{ fontSize: '0.68rem', fontWeight: 700, color: isMet ? '#047857' : '#b91c1c', display: 'flex', alignItems: 'center', gap: '0.15rem' }}>
                          {isMet ? '✓ Đạt' : '✗ Chưa đạt'}
                        </span>
                      </div>
                      <div style={{ fontSize: '0.7rem', color: '#64748b' }}>
                        Yêu cầu: <span style={{ color: '#475569', fontWeight: 500 }}>{check.required_value}</span>
                      </div>
                      <div style={{ fontSize: '0.7rem', color: '#64748b' }}>
                        Thực tế: <span style={{ color: isMet ? '#047857' : '#b91c1c', fontWeight: 600 }}>{check.actual_value}</span>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {/* Strengths & Weaknesses Panel */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '1.5rem', marginTop: '1.5rem' }}>
            
            {/* Strengths */}
            <div style={{ padding: '1.25rem', border: '1px solid #a7f3d0', backgroundColor: '#f0fdf4', borderRadius: '0.5rem' }}>
              <h3 style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', color: '#15803d', fontWeight: 700, fontSize: '0.9rem', marginBottom: '0.75rem', marginTop: 0 }}>
                <CheckCircle size={16} />
                <span>Điểm mạnh nổi bật</span>
              </h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                {(strengths || []).length > 0 ? (
                  (strengths || []).map((strength: any, index: number) => {
                    const text = typeof strength === 'object' && strength !== null ? (strength.area || strength.name || JSON.stringify(strength)) : strength;
                    return (
                      <div key={index} style={{ display: 'flex', gap: '0.5rem', alignItems: 'flex-start' }}>
                        <span style={{ color: '#15803d', fontWeight: 'bold' }}>✓</span>
                        <span style={{ fontSize: '0.82rem', color: '#1e293b', lineHeight: '1.4' }}>{text}</span>
                      </div>
                    );
                  })
                ) : (
                  <span style={{ color: '#64748b', fontSize: '0.85rem', fontStyle: 'italic' }}>Không ghi nhận điểm mạnh.</span>
                )}
              </div>
            </div>

            {/* Weaknesses */}
            <div style={{ padding: '1.25rem', border: '1px solid #fca5a5', backgroundColor: '#fef2f2', borderRadius: '0.5rem' }}>
              <h3 style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', color: '#b91c1c', fontWeight: 700, fontSize: '0.9rem', marginBottom: '0.75rem', marginTop: 0 }}>
                <AlertCircle size={16} style={{ color: '#b91c1c' }} />
                <span>Điểm cần cải thiện</span>
              </h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                {(weaknesses || []).length > 0 ? (
                  (weaknesses || []).map((weakness: any, index: number) => {
                    const text = typeof weakness === 'object' && weakness !== null ? (weakness.area || weakness.name || JSON.stringify(weakness)) : weakness;
                    return (
                      <div key={index} style={{ display: 'flex', gap: '0.5rem', alignItems: 'flex-start' }}>
                        <span style={{ color: '#b91c1c', fontWeight: 'bold' }}>✗</span>
                        <span style={{ fontSize: '0.82rem', color: '#1e293b', lineHeight: '1.4' }}>{text}</span>
                      </div>
                    );
                  })
                ) : (
                  <span style={{ color: '#64748b', fontSize: '0.85rem', fontStyle: 'italic' }}>Không ghi nhận điểm yếu.</span>
                )}
              </div>
            </div>

          </div>

          {/* Recommendations */}
          <div style={{ backgroundColor: '#f8fafc', border: '1px solid #cbd5e1', borderRadius: '0.5rem', padding: '1.25rem', marginTop: '1.5rem' }}>
            <h3 style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.9rem', fontWeight: 700, color: '#0f172a', borderBottom: '1px solid #e2e8f0', paddingBottom: '0.5rem', margin: '0 0 0.75rem 0' }}>
              <Lightbulb size={18} style={{ color: '#eab308' }} />
              <span>Khuyến nghị từ AI</span>
            </h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
              {(recommendations || []).length > 0 ? (
                (recommendations || []).map((suggestion: any, index: number) => {
                  const text = typeof suggestion === 'object' && suggestion !== null ? (suggestion.question || suggestion.suggestion || JSON.stringify(suggestion)) : suggestion;
                  return (
                    <div key={index} style={{ display: 'flex', gap: '0.5rem', alignItems: 'flex-start' }}>
                      <span style={{ color: '#ea580c', fontWeight: 'bold' }}>➔</span>
                      <span style={{ fontSize: '0.82rem', color: '#334155', lineHeight: '1.4' }}>{text}</span>
                    </div>
                  );
                })
              ) : (
                <p style={{ fontSize: '0.82rem', color: '#64748b', fontStyle: 'italic', margin: 0 }}>Không có đề xuất thêm.</p>
              )}
            </div>
          </div>
        </section>







        {/* ── Accordion QA Section ── */}
        <section className={styles.questionsSection}>
          <h2 className={styles.sectionTitle}>Chi tiết câu hỏi &amp; Trả lời</h2>

          {session.questions.length === 0 ? (
            <div style={{ backgroundColor: '#ffffff', border: '1px solid #e2e8f0', borderRadius: '0.75rem', padding: '3rem', textAlign: 'center', color: '#94a3b8', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
              <AlertTriangle size={32} style={{ color: '#eab308' }} />
              <p style={{ marginTop: '0.5rem', fontSize: '0.9rem', color: '#64748b' }}>
                {isPostInterviewEvaluated 
                  ? 'Không có câu hỏi nào được trả lời trong phiên phỏng vấn này.'
                  : 'Buổi phỏng vấn chưa được thực hiện.'}
              </p>
              {!isPostInterviewEvaluated && (
                <Link href={`/interview/session/${session.id}`} className={styles.primaryButton} style={{ marginTop: '1rem', textDecoration: 'none' }}>
                  Bắt đầu phỏng vấn ngay
                </Link>
              )}
            </div>
          ) : (
            <div className={styles.accordionList}>
              {session.questions.map((q, index) => {
                const isExpanded = expandedIndexes.includes(index);
                return (
                  <div key={index} className={styles.accordionItem}>
                    {/* Header */}
                    <button className={styles.accordionHeader} onClick={() => toggleAccordion(index)}>
                      <div className={styles.headerMain}>
                        <div className={styles.headerMeta}>
                          <span className={styles.qNum}>CÂU HỎI {index + 1}</span>
                          <span className={styles.topicBadge}>
                            {q.topicTag || (typeof q.question === 'object' && q.question !== null ? (q.question as any).topic : '')}
                          </span>
                          {q.isDeepDive && (
                            <span className={styles.deepDiveBadge}>Hỏi sâu (Deep dive)</span>
                          )}
                        </div>
                        <div className={styles.qText}>
                          {typeof q.question === 'object' && q.question !== null ? (q.question as any).question : q.question}
                        </div>
                      </div>

                      <div className={styles.headerRight}>
                        <div className={styles.qScore}>
                          <span className={styles.qScoreNum}>{q.score}</span>
                          <span className={styles.qScoreLabel}>Điểm</span>
                        </div>
                        <span className={`${styles.arrowIcon} ${isExpanded ? styles.arrowExpanded : ''}`}>
                          ▼
                        </span>
                      </div>
                    </button>

                    {/* Body */}
                    {isExpanded && (
                      <div className={styles.accordionBody}>
                        {/* Candidate Answer */}
                        <div className={styles.sectionBlock}>
                          <h4 style={{ display: 'inline-flex', alignItems: 'center', gap: '0.4rem' }}>
                            <MessageSquare size={16} style={{ color: '#4f46e5' }} />
                            <span>Câu trả lời của bạn</span>
                          </h4>
                          <p className={styles.userAnswerText}>{q.answer}</p>
                        </div>

                        {/* AI Strengths & Improvements */}
                        <div className={styles.sectionBlock}>
                          <h4 style={{ display: 'inline-flex', alignItems: 'center', gap: '0.4rem' }}>
                            <BarChart3 size={16} style={{ color: '#4f46e5' }} />
                            <span>Phân tích câu trả lời của AI</span>
                          </h4>
                          <div className={styles.aiFeedbackGrid}>
                            <div className={`${styles.feedbackBox} ${styles.feedbackStrength}`}>
                              <strong style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem', marginBottom: '0.25rem' }}>
                                <CheckCircle2 size={14} style={{ color: '#10b981' }} />
                                <span>Điểm mạnh:</span>
                              </strong>
                              <div>{q.strengths}</div>
                            </div>
                            <div className={`${styles.feedbackBox} ${styles.feedbackImprovement}`}>
                              <strong style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem', marginBottom: '0.25rem' }}>
                                <XCircle size={14} style={{ color: '#f59e0b' }} />
                                <span>Cần cải thiện:</span>
                              </strong>
                              <div>{q.improvements}</div>
                            </div>
                          </div>
                        </div>

                        {/* Suggested Answer */}
                        <div className={styles.sectionBlock}>
                          <h4 style={{ display: 'inline-flex', alignItems: 'center', gap: '0.4rem' }}>
                            <Lightbulb size={16} style={{ color: '#4f46e5' }} />
                            <span>Gợi ý câu trả lời tốt hơn từ AI</span>
                          </h4>
                          <div className={styles.suggestedAnswerBox}>
                            {q.suggestedAnswer}
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </section>

        {/* CTAs Button Bar */}
        <div className={styles.actions}>
          <Link href="/history" className={styles.secondaryButton}>
            Quay lại Lịch sử
          </Link>
          {isPostInterviewEvaluated ? (
            <Link href="/interview/new" className={styles.primaryButton}>
              Luyện tập lại
            </Link>
          ) : (
            <Link href={`/interview/session/${session.id}`} className={styles.primaryButton}>
              Bắt đầu phỏng vấn
            </Link>
          )}
        </div>
      </main>

    </div>
  );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import styles from './login.module.css';
import axiosClient from '@/lib/axiosClient';
import { useAuthStore } from '@/store/authStore';

export default function LoginPage() {
  const router = useRouter();
  const { login } = useAuthStore();

  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({ email: '', password: '' });
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const { data } = await axiosClient.post('/api/auth/login', {
        email: form.email,
        password: form.password,
      });

      // data: { token, id, username, email, role, phoneNumber, avatarUrl, defaultResumeId }
      login(
        {
          id: data.id,
          username: data.username,
          email: data.email,
          role: data.role,
          phoneNumber: data.phoneNumber ?? null,
          avatarUrl: data.avatarUrl ?? null,
          defaultResumeId: data.defaultResumeId ?? null,
        },
        data.token
      );

      if (data.role === 'ADMIN') {
        router.push('/admin/rules');
      } else {
        router.push('/');
      }
    } catch (err: any) {
      const msg =
        err?.response?.data?.detail ||
        err?.response?.data?.message ||
        'Email hoặc mật khẩu không đúng. Vui lòng thử lại.';
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.page}>
      <div className={styles.bgBlob1} />
      <div className={styles.bgBlob2} />

      <div className={styles.wrap}>
        <div className={styles.card}>
          {/* Header */}
          <div className={styles.cardHead}>
            <div className={styles.cardIcon}>
              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <circle cx="12" cy="12" r="10" />
                <polyline points="12 6 12 12 16 14" />
              </svg>
            </div>
            <h1 className={styles.cardTitle}>Chào mừng trở lại!</h1>
            <p className={styles.cardSub}>Đăng nhập để tiếp tục luyện tập</p>
          </div>

          {/* Global error banner */}
          {error && (
            <div style={{
              background: 'rgba(239,68,68,0.12)',
              border: '1px solid rgba(239,68,68,0.4)',
              borderRadius: '10px',
              padding: '10px 14px',
              marginBottom: '16px',
              color: '#f87171',
              fontSize: '13px',
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
            }}>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <circle cx="12" cy="12" r="10" /><line x1="12" y1="8" x2="12" y2="12" /><line x1="12" y1="16" x2="12.01" y2="16" />
              </svg>
              {error}
            </div>
          )}

          {/* Form */}
          <form onSubmit={handleSubmit} className={styles.form}>
            {/* Email */}
            <div className={styles.field}>
              <label htmlFor="email" className={styles.label}>Email</label>
              <div className={styles.inputWrap}>
                <span className={styles.inputIcon}>
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z" /><polyline points="22,6 12,13 2,6" />
                  </svg>
                </span>
                <input
                  id="email"
                  type="email"
                  placeholder="you@example.com"
                  required
                  value={form.email}
                  onChange={(e) => setForm({ ...form, email: e.target.value })}
                  className={styles.input}
                  autoComplete="email"
                />
              </div>
            </div>

            {/* Password */}
            <div className={styles.field}>
              <div className={styles.fieldLabelRow}>
                <label htmlFor="password" className={styles.label}>Mật khẩu</label>
                <Link href="#" className={styles.forgotLink}>Quên mật khẩu?</Link>
              </div>
              <div className={styles.inputWrap}>
                <span className={styles.inputIcon}>
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <rect x="3" y="11" width="18" height="11" rx="2" ry="2" /><path d="M7 11V7a5 5 0 0 1 10 0v4" />
                  </svg>
                </span>
                <input
                  id="password"
                  type={showPassword ? 'text' : 'password'}
                  placeholder="••••••••"
                  required
                  value={form.password}
                  onChange={(e) => setForm({ ...form, password: e.target.value })}
                  className={`${styles.input} ${styles.inputWithEye}`}
                  autoComplete="current-password"
                />
                <button type="button" className={styles.eyeBtn} onClick={() => setShowPassword(!showPassword)}>
                  {showPassword ? (
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                      <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24" /><line x1="1" y1="1" x2="23" y2="23" />
                    </svg>
                  ) : (
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                      <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" /><circle cx="12" cy="12" r="3" />
                    </svg>
                  )}
                </button>
              </div>
            </div>

            {/* Submit */}
            <button type="submit" disabled={loading} className={styles.submitBtn}>
              {loading ? (
                <svg width="16" height="16" className={styles.spinner} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M21 12a9 9 0 1 1-6.219-8.56" />
                </svg>
              ) : (
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <line x1="5" y1="12" x2="19" y2="12" /><polyline points="12 5 19 12 12 19" />
                </svg>
              )}
              {loading ? 'Đang đăng nhập...' : 'Đăng nhập'}
            </button>
          </form>

          <div className={styles.divider}>
            <div className={styles.dividerLine} />
            <span className={styles.dividerText}>hoặc</span>
            <div className={styles.dividerLine} />
          </div>

          <p className={styles.footerText}>
            Chưa có tài khoản?{' '}
            <Link href="/register" className={styles.footerLink}>Đăng ký miễn phí</Link>
          </p>
        </div>

        <Link href="/" className={styles.backLink}>← Quay lại trang chủ</Link>
      </div>
    </div>
  );
}

'use client';

import type { LucideIcon } from 'lucide-react';
import {
  BarChart3, CalendarDays, Coins, Eye, FileJson2, LockKeyhole,
  MapPin, PencilLine, Sparkles, Star, Upload, UserRound,
  BriefcaseBusiness, ChevronDown, CheckCircle, AlertCircle, X, FileText
} from 'lucide-react';
import { useState, useRef, useEffect } from 'react';
import styles from './profile.module.css';
import ProtectedRoute from '@/components/auth/ProtectedRoute';
import { useAuthStore } from '@/store/authStore';
import axiosClient from '@/lib/axiosClient';
import axios from 'axios';
import dynamic from 'next/dynamic';
const PdfViewerModal = dynamic(() => import('@/components/common/PdfViewerModal'), { ssr: false });

// ── Types ─────────────────────────────────────────────────────────────────────

type StatItem = {
  label: string;
  value: number;
  icon: LucideIcon;
  iconClass: string;
};

type ResumeOption = {
  id: number;
  name: string;
};

// ── Toast helper (lightweight, no external dep) ───────────────────────────────

type ToastState = { type: 'success' | 'error'; message: string } | null;

function Toast({ toast }: { toast: ToastState }) {
  if (!toast) return null;
  const isSuccess = toast.type === 'success';
  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: '0.5rem',
        padding: '0.75rem 1rem',
        borderRadius: '0.5rem',
        marginBottom: '1rem',
        fontSize: '0.875rem',
        background: isSuccess ? 'rgba(34,197,94,0.12)' : 'rgba(239,68,68,0.12)',
        border: `1px solid ${isSuccess ? 'rgba(34,197,94,0.4)' : 'rgba(239,68,68,0.4)'}`,
        color: isSuccess ? '#4ade80' : '#f87171',
      }}
    >
      {isSuccess
        ? <CheckCircle size={15} />
        : <AlertCircle size={15} />}
      {toast.message}
    </div>
  );
}

// ── Admin-only Stats block ────────────────────────────────────────────────────

function AdminStatsBlock({ stats }: { stats: StatItem[] }) {
  return (
    <div className={styles.card}>
      <div className={styles.cardHead}>
        <div>
          <h2 className={styles.cardTitle}>Thống kê tài khoản</h2>
          <p className={styles.cardSubText}>Hoạt động phân tích và điểm số trong hệ thống</p>
        </div>
        <span className={styles.statsBrandText}>ATS - CAREER</span>
      </div>

      <div className={styles.statsGrid}>
        {stats.map((stat, idx) => (
          <div key={idx} className={styles.statCard}>
            <div className={styles.statCardHeader}>
              <span className={styles.statCardLabel}>{stat.label}</span>
              <span className={`${styles.statCardIcon} ${stat.iconClass}`}>
                <stat.icon size={14} strokeWidth={2.5} />
              </span>
            </div>
            <span className={styles.statCardVal}>{stat.value}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── Page ──────────────────────────────────────────────────────────────────────

export default function ProfilePage() {
  const { user, updateUser } = useAuthStore();
  const fileInputRef = useRef<HTMLInputElement>(null);

  // ── Personal info state ──────────────────────────────────────────
  const [fullName, setFullName] = useState(user?.username ?? '');
  const [phone, setPhone] = useState(user?.phoneNumber ?? '');
  const [isEditing, setIsEditing] = useState(false);
  const [infoLoading, setInfoLoading] = useState(false);
  const [infoToast, setInfoToast] = useState<ToastState>(null);

  // Sync inputs with authStore when user loads or updates
  useEffect(() => {
    if (user) {
      setFullName(user.username);
      setPhone(user.phoneNumber ?? '');
    }
  }, [user]);

  const handleSaveProfile = async () => {
    if (!fullName.trim()) {
      setInfoToast({ type: 'error', message: 'Họ và tên không được để trống.' });
      return;
    }

    setInfoLoading(true);
    setInfoToast(null);

    try {
      const { data } = await axiosClient.put('/api/auth/profile', {
        username: fullName,
        phoneNumber: phone,
        avatarUrl: user?.avatarUrl,
      });

      updateUser({
        username: data.username,
        phoneNumber: data.phoneNumber,
        avatarUrl: data.avatarUrl,
      });

      setInfoToast({ type: 'success', message: 'Cập nhật thông tin cá nhân thành công!' });
      setIsEditing(false);
    } catch (err: any) {
      const msg =
        err?.response?.data?.detail ||
        err?.response?.data?.message ||
        'Cập nhật thất bại. Vui lòng thử lại sau.';
      setInfoToast({ type: 'error', message: msg });
    } finally {
      setInfoLoading(false);
      setTimeout(() => setInfoToast(null), 5000);
    }
  };

  const handleCancelEdit = () => {
    setFullName(user?.username ?? '');
    setPhone(user?.phoneNumber ?? '');
    setIsEditing(false);
    setInfoToast(null);
  };

  // ── Avatar Upload State ──────────────────────────────────────────
  const [avatarLoading, setAvatarLoading] = useState(false);
  const [avatarToast, setAvatarToast] = useState<ToastState>(null);

  const triggerAvatarUpload = () => {
    fileInputRef.current?.click();
  };

  const handleAvatarChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const file = files[0];
    const maxSize = 2 * 1024 * 1024; // 2MB

    if (file.size > maxSize) {
      setAvatarToast({ type: 'error', message: 'Kích thước ảnh đại diện không được vượt quá 2MB.' });
      return;
    }

    const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp', 'image/gif'];
    if (!allowedTypes.includes(file.type)) {
      setAvatarToast({ type: 'error', message: 'Chỉ chấp nhận các định dạng ảnh: JPG, PNG, WebP hoặc GIF.' });
      return;
    }

    setAvatarLoading(true);
    setAvatarToast(null);

    const formData = new FormData();
    formData.append('file', file);

    try {
      const token = useAuthStore.getState().token;
      const { data } = await axios.post('/api/profile/avatar', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
          'Authorization': `Bearer ${token}`
        },
      });

      updateUser({
        avatarUrl: data.avatarUrl,
      });

      setAvatarToast({ type: 'success', message: 'Cập nhật ảnh đại diện thành công!' });
    } catch (err: any) {
      const msg =
        err?.response?.data?.detail ||
        err?.response?.data?.message ||
        'Tải ảnh lên thất bại. Vui lòng thử lại sau.';
      setAvatarToast({ type: 'error', message: msg });
    } finally {
      setAvatarLoading(false);
      // Reset input value to allow uploading same file again
      if (fileInputRef.current) fileInputRef.current.value = '';
      setTimeout(() => setAvatarToast(null), 5000);
    }
  };

  // Helper to construct fully qualified image URL if it's stored locally
  const getAvatarUrl = (url: string | null | undefined) => {
    if (!url) return '';
    if (url.startsWith('http://') || url.startsWith('https://')) return url;
    const baseUrl = process.env.NEXT_PUBLIC_API_BASE_URL ?? 'http://localhost:8081';
    return `${baseUrl.replace(/\/$/, '')}/${url.replace(/^\//, '')}`;
  };

  // ── Default CV state ─────────────────────────────────────────────
  const [dbResumes, setDbResumes] = useState<any[]>([]);
  const [selectedResumeId, setSelectedResumeId] = useState<number>(
    user?.defaultResumeId ? Number(user.defaultResumeId) : 0
  );
  const [cvLoading, setCvLoading] = useState(false);
  const [cvToast, setCvToast] = useState<ToastState>(null);
  const fileInputCvRef = useRef<HTMLInputElement>(null);

  // PDF Viewer Modal State
  const [viewerOpen, setViewerOpen] = useState(false);
  const [viewerUrl, setViewerUrl] = useState('');
  const [viewerTitle, setViewerTitle] = useState('');

  useEffect(() => {
    async function loadResumes() {
      try {
        const token = useAuthStore.getState().token;
        const res = await fetch('/api/resumes', {
          headers: {
            'Authorization': `Bearer ${token}`
          }
        });
        if (res.ok) {
          const data = await res.json();
          setDbResumes(data);
        }
      } catch (err) {
        console.error('Error loading resumes:', err);
      }
    }
    loadResumes();
  }, []);

  // Update selectedResumeId when user defaultResumeId is loaded or changes
  useEffect(() => {
    if (user?.defaultResumeId) {
      setSelectedResumeId(Number(user.defaultResumeId));
    }
  }, [user?.defaultResumeId]);

  const handleCvUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const file = files[0];
    const maxSize = 10 * 1024 * 1024; // 10MB

    if (file.size > maxSize) {
      setCvToast({ type: 'error', message: 'Kích thước tệp CV không được vượt quá 10MB.' });
      return;
    }

    if (file.type !== 'application/pdf' && !file.name.endsWith('.pdf')) {
      setCvToast({ type: 'error', message: 'CV mặc định phải ở định dạng PDF (.pdf).' });
      return;
    }

    setCvLoading(true);
    setCvToast(null);

    const formData = new FormData();
    formData.append('file', file);

    try {
      const token = useAuthStore.getState().token;
      const { data } = await axios.post('/api/profile/default-resume', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
          'Authorization': `Bearer ${token}`
        },
      });

      if (data.success) {
        updateUser({
          defaultResumeId: String(data.defaultResumeId),
        });
        setDbResumes(prev => [data.resume, ...prev]);
        setCvToast({ type: 'success', message: 'Đã cập nhật CV mặc định thành công!' });
      }
    } catch (err: any) {
      console.error('Error uploading default CV:', err);
      setCvToast({ type: 'error', message: 'Tải CV lên thất bại. Vui lòng thử lại sau.' });
    } finally {
      setCvLoading(false);
      if (fileInputCvRef.current) fileInputCvRef.current.value = '';
      setTimeout(() => setCvToast(null), 5000);
    }
  };

  // ── Change password state ────────────────────────────────────────
  const [currentPass, setCurrentPass] = useState('');
  const [newPass, setNewPass] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [pwLoading, setPwLoading] = useState(false);
  const [pwToast, setPwToast] = useState<ToastState>(null);

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    setPwToast(null);

    if (newPass !== confirmPass) {
      setPwToast({ type: 'error', message: 'Mật khẩu mới và xác nhận không khớp.' });
      return;
    }

    setPwLoading(true);
    try {
      await axiosClient.post('/api/auth/change-password', {
        currentPassword: currentPass,
        newPassword: newPass,
        confirmPassword: confirmPass,
      });

      // Clear form on success
      setCurrentPass('');
      setNewPass('');
      setConfirmPass('');
      setPwToast({ type: 'success', message: 'Đổi mật khẩu thành công!' });
    } catch (err: unknown) {
      const axiosErr = err as { response?: { data?: { detail?: string; message?: string } } };
      const msg =
        axiosErr?.response?.data?.detail ||
        axiosErr?.response?.data?.message ||
        'Đổi mật khẩu thất bại. Vui lòng kiểm tra lại mật khẩu hiện tại.';
      setPwToast({ type: 'error', message: msg });
    } finally {
      setPwLoading(false);
      setTimeout(() => setPwToast(null), 5000);
    }
  };

  // ── Admin stats (only rendered for ADMIN role) ───────────────────
  const stats: StatItem[] = [
    { label: 'LƯỢT PHÂN TÍCH CV', value: 0, icon: BarChart3, iconClass: styles.statIconBlue },
    { label: 'PHÂN TÍCH HÔM NAY', value: 0, icon: CalendarDays, iconClass: styles.statIconOrange },
    { label: 'ĐIỂM TRUNG BÌNH', value: 0, icon: Star, iconClass: styles.statIconGreen },
    { label: 'COINS', value: 0, icon: Coins, iconClass: styles.statIconAmber },
  ];

  return (
    <ProtectedRoute>
      <div className={styles.page}>
        <div className={styles.inner}>

          {/* ── Top Banner ────────────────────────────────────────── */}
          <div className={styles.banner}>
            <div className={styles.bannerBgCircle}>
              <svg width="240" height="240" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <circle cx="12" cy="12" r="10" />
              </svg>
            </div>

            {/* Avatar: show image if avatarUrl exists, else placeholder icon */}
            <div className={styles.avatarBig}>
              {user?.avatarUrl ? (
                <img
                  src={getAvatarUrl(user.avatarUrl)}
                  alt="Avatar"
                  style={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: '50%' }}
                />
              ) : (
                <UserRound size={30} strokeWidth={2.4} />
              )}
            </div>

            <div className={styles.bannerInfo}>
              <span className={styles.bannerSub}>HỒ SƠ ỨNG VIÊN</span>
              <h1 className={styles.bannerName}>{user?.username ?? '...'}</h1>
              <p className={styles.bannerEmail}>{user?.email ?? ''}</p>
            </div>
          </div>

          {/* ── Card 1: Thông tin cá nhân ─────────────────────────── */}
          <div className={styles.card}>
            <div className={styles.cardHead}>
              <div>
                <h2 className={styles.cardTitle}>Thông tin cá nhân</h2>
                <p className={styles.cardSubText}>Quản lý thông tin tài khoản và cài đặt cá nhân</p>
              </div>
              {!isEditing ? (
                <button className={styles.btnEdit} onClick={() => setIsEditing(true)}>
                  <PencilLine size={12} strokeWidth={2.5} />
                  Sửa
                </button>
              ) : (
                <button className={styles.btnEdit} onClick={handleCancelEdit} style={{ color: '#ef4444', borderColor: 'rgba(239,68,68,0.2)' }}>
                  <X size={12} strokeWidth={2.5} />
                  Hủy
                </button>
              )}
            </div>

            <div className={styles.grid}>
              <div className={styles.field}>
                <label className={styles.label}>Họ và tên</label>
                <input
                  type="text"
                  value={fullName}
                  onChange={(e) => setFullName(e.target.value)}
                  className={`${styles.input} ${!isEditing ? styles.inputDisabled : ''}`}
                  disabled={!isEditing}
                />
              </div>
              <div className={styles.field}>
                <label className={styles.label}>Email</label>
                <input
                  type="email"
                  value={user?.email ?? ''}
                  disabled
                  className={`${styles.input} ${styles.inputDisabled}`}
                />
                <span className={styles.helpText}>Email không thể thay đổi</span>
              </div>
              <div className={styles.field}>
                <label className={styles.label}>Số điện thoại</label>
                <input
                  type="tel"
                  value={phone}
                  placeholder="Chưa cập nhật"
                  onChange={(e) => setPhone(e.target.value)}
                  className={`${styles.input} ${!isEditing ? styles.inputDisabled : ''}`}
                  disabled={!isEditing}
                />
              </div>
              <div className={styles.field}>
                <label className={styles.label}>Vai trò</label>
                <input
                  type="text"
                  value={user?.role ?? ''}
                  disabled
                  className={`${styles.input} ${styles.inputDisabled}`}
                />
              </div>
            </div>

            <Toast toast={infoToast} />

            {isEditing && (
              <button
                onClick={handleSaveProfile}
                disabled={infoLoading}
                className={styles.btnPrimary}
                style={{ marginTop: '1.25rem', width: 'fit-content' }}
              >
                {infoLoading ? (
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ animation: 'spin 0.9s linear infinite' }}>
                    <path d="M21 12a9 9 0 1 1-6.219-8.56" />
                  </svg>
                ) : (
                  <CheckCircle size={14} strokeWidth={2.5} />
                )}
                {infoLoading ? 'Đang lưu...' : 'Lưu thay đổi'}
              </button>
            )}
          </div>

          {/* ── Card 2: Ảnh đại diện & CV mặc định ───────────────── */}
          <div className={styles.card}>
            <div className={styles.cardHead}>
              <div>
                <span className={styles.badgeOrangeText}>Ứng viên</span>
                <h2 className={styles.cardTitle} style={{ marginTop: '0.375rem' }}>
                  Ảnh đại diện &amp; CV mặc định
                </h2>
                <p className={styles.cardSubText}>
                  Avatar lưu trên hệ thống lưu trữ. CV mặc định tự động điền bảng candidates
                  và dữ liệu JSON Resume trong hệ thống.
                </p>
              </div>
            </div>

            <div className={styles.grid}>
              {/* Left: Avatar upload */}
              <div className={styles.field} style={{ gap: '0.75rem' }}>
                <h3 className={styles.label} style={{ color: '#475569' }}>Ảnh đại diện</h3>
                <p className={styles.cardSubText} style={{ margin: 0 }}>JPG, PNG, WebP hoặc GIF — Tối đa 2MB.</p>
                
                <Toast toast={avatarToast} />
                
                <button
                  className={styles.btnPrimary}
                  style={{ width: 'fit-content' }}
                  onClick={triggerAvatarUpload}
                  disabled={avatarLoading}
                >
                  {avatarLoading ? (
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ animation: 'spin 0.9s linear infinite' }}>
                      <path d="M21 12a9 9 0 1 1-6.219-8.56" />
                    </svg>
                  ) : (
                    <Upload size={14} strokeWidth={2.5} />
                  )}
                  {avatarLoading ? 'Đang tải lên...' : 'Tải ảnh lên'}
                </button>
                
                <input
                  type="file"
                  ref={fileInputRef}
                  onChange={handleAvatarChange}
                  style={{ display: 'none' }}
                  accept="image/jpeg, image/jpg, image/png, image/webp, image/gif"
                />
              </div>

              {/* Right: Default CV */}
              <div className={styles.field} style={{ gap: '0.75rem' }}>
                <h3 className={styles.label} style={{ color: '#475569' }}>CV mặc định (PDF)</h3>
                <p className={styles.cardSubText} style={{ margin: 0 }}>
                  Dùng để tự động chọn khi khởi tạo phiên phỏng vấn mới.
                </p>

                <div className={styles.field} style={{ gap: '0.875rem' }}>
                  <Toast toast={cvToast} />

                  {/* Active default CV display */}
                  {user?.defaultResumeId ? (
                    (() => {
                      const defResume = dbResumes.find(r => String(r.id) === String(user.defaultResumeId));
                      return (
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem', width: '100%' }}>
                          <div style={{
                            border: '1px solid #ffedd5',
                            borderRadius: '0.75rem',
                            padding: '0.75rem 1rem',
                            backgroundColor: '#fff7ed',
                            display: 'flex',
                            alignItems: 'center',
                            gap: '0.75rem',
                          }}>
                            <FileText size={24} style={{ color: '#ea580c', flexShrink: 0 }} />
                            <div style={{ minWidth: 0, flex: 1 }}>
                              <p style={{ margin: 0, fontWeight: 600, fontSize: '0.85rem', color: '#1e293b', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                {defResume?.file_name || 'Đang tải thông tin CV...'}
                              </p>
                              {defResume && (
                                <p style={{ margin: 0, fontSize: '0.75rem', color: '#64748b' }}>
                                  Ngày lưu: {new Date(defResume.created_at).toLocaleDateString('vi-VN')}
                                </p>
                              )}
                            </div>
                          </div>

                          <div style={{ display: 'flex', gap: '0.5rem' }}>
                            {defResume?.file_url && (
                              <button 
                                className={styles.btnSecondary} 
                                onClick={() => {
                                  setViewerUrl(defResume.file_url);
                                  setViewerTitle(`CV mặc định: ${defResume.file_name}`);
                                  setViewerOpen(true);
                                }}
                                style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem', fontSize: '0.8rem', padding: '0.5rem 0.85rem' }}
                              >
                                <Eye size={12} strokeWidth={2.5} />
                                Xem CV
                              </button>
                            )}
                            <button 
                              className={styles.btnPrimary} 
                              onClick={() => fileInputCvRef.current?.click()}
                              disabled={cvLoading}
                              style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem', fontSize: '0.8rem', padding: '0.5rem 0.85rem' }}
                            >
                              <Upload size={12} strokeWidth={2.5} />
                              {cvLoading ? 'Đang tải...' : 'Thay đổi CV'}
                            </button>
                          </div>
                        </div>
                      );
                    })()
                  ) : (
                    <div>
                      <button 
                        className={styles.btnPrimary} 
                        onClick={() => fileInputCvRef.current?.click()}
                        disabled={cvLoading}
                        style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}
                      >
                        <Upload size={14} strokeWidth={2.5} />
                        {cvLoading ? 'Đang tải...' : 'Tải lên CV mặc định'}
                      </button>
                      <p style={{ fontSize: '0.75rem', color: '#94a3b8', marginTop: '0.35rem' }}>Chấp nhận tệp định dạng PDF dưới 10MB.</p>
                    </div>
                  )}

                  {/* Optional select from existing list */}
                  {dbResumes.length > 0 && (
                    <div style={{ borderTop: '1px dashed #e2e8f0', paddingTop: '0.75rem', marginTop: '0.25rem' }}>
                      <p style={{ fontSize: '0.78rem', color: '#64748b', marginBottom: '0.35rem', fontWeight: 500 }}>Hoặc chọn từ danh sách CV đã tải lên:</p>
                      <div style={{ display: 'flex', gap: '0.5rem', width: '100%' }}>
                        <div className={styles.selectWrap} style={{ flex: 1 }}>
                          <select
                            value={selectedResumeId || ''}
                            onChange={(e) => setSelectedResumeId(e.target.value ? parseInt(e.target.value, 10) : 0)}
                            className={styles.select}
                          >
                            <option value="">-- Chọn CV trong danh sách --</option>
                            {dbResumes.map((r) => (
                              <option key={r.id} value={r.id}>{r.file_name}</option>
                            ))}
                          </select>
                          <div className={styles.selectIcon}>
                            <ChevronDown size={12} strokeWidth={2.5} />
                          </div>
                        </div>
                        <button 
                          className={styles.btnSecondary}
                          onClick={async () => {
                            if (!selectedResumeId) return;
                            setCvLoading(true);
                            try {
                              const token = useAuthStore.getState().token;
                              const res = await fetch('/api/profile/default-resume/set', {
                                method: 'POST',
                                headers: {
                                  'Content-Type': 'application/json',
                                  'Authorization': `Bearer ${token}`
                                },
                                body: JSON.stringify({ resumeId: selectedResumeId })
                              });
                              if (res.ok) {
                                updateUser({ defaultResumeId: String(selectedResumeId) });
                                setCvToast({ type: 'success', message: 'Đặt làm CV mặc định thành công!' });
                              } else {
                                setCvToast({ type: 'error', message: 'Lỗi đặt CV mặc định.' });
                              }
                            } catch (e) {
                              setCvToast({ type: 'error', message: 'Lỗi đặt CV mặc định.' });
                            } finally {
                              setCvLoading(false);
                              setTimeout(() => setCvToast(null), 3000);
                            }
                          }}
                          style={{ fontSize: '0.8rem', padding: '0.5rem 0.85rem' }}
                        >
                          Chọn
                        </button>
                      </div>
                    </div>
                  )}

                  <input
                    type="file"
                    ref={fileInputCvRef}
                    onChange={handleCvUpload}
                    style={{ display: 'none' }}
                    accept="application/pdf"
                  />
                </div>
              </div>
            </div>
          </div>

          {/* ── Card 3: Sở thích công việc ────────────────────────── */}
          <div className={`${styles.card} ${styles.cardOrangeSide}`}>
            <div className={styles.cardHead}>
              <div>
                <span className={styles.badgeOrangeText} style={{ backgroundColor: '#fff7ed', color: '#ea580c' }}>
                  Gợi ý việc làm
                </span>
                <h2 className={styles.cardTitle} style={{ marginTop: '0.375rem' }}>Sở thích công việc</h2>
                <p className={styles.cardSubText}>
                  Cập nhật địa điểm và lĩnh vực mong muốn để nhận gợi ý việc làm phù hợp.
                </p>
              </div>
              <button className={styles.btnPrimaryOrange}>
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M12 20h9" /><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z" />
                </svg>
                Chỉnh sửa gợi ý việc làm
              </button>
            </div>

            <div className={styles.chipContainer}>
              <div className={styles.chipGroup}>
                <h4 className={styles.chipGroupTitle}>Địa điểm ưu tiên</h4>
                <div className={styles.chips}>
                  <span className={styles.chip}>
                    <MapPin size={12} strokeWidth={2.5} /> Hồ Chí Minh
                  </span>
                </div>
              </div>
              <div className={styles.chipGroup}>
                <h4 className={styles.chipGroupTitle}>Nhóm ngành quan tâm</h4>
                <div className={styles.chips}>
                  <span className={styles.chip}>
                    <BriefcaseBusiness size={12} strokeWidth={2.5} /> BA - IT
                  </span>
                </div>
              </div>
            </div>
          </div>

