        isOpen={viewerOpen}
        onClose={() => setViewerOpen(false)}
        pdfUrl={viewerUrl}
        title={viewerTitle}
      />
    </ProtectedRoute>
  );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import styles from './register.module.css';
import axiosClient from '@/lib/axiosClient';

export default function RegisterPage() {
  const router = useRouter();

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({ fullName: '', email: '', password: '', confirmPassword: '' });
  const [passwordError, setPasswordError] = useState('');
  const [apiError, setApiError] = useState('');
  const [success, setSuccess] = useState(false);

  const strength = (() => {
    const p = form.password;
    if (!p) return null;
    if (p.length < 6) return { label: 'Yếu', cls: styles.strengthWeak, w: '33%' };
    if (p.length < 10) return { label: 'Trung bình', cls: styles.strengthMedium, w: '66%' };
    return { label: 'Mạnh', cls: styles.strengthStrong, w: '100%' };
  })();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (form.password !== form.confirmPassword) {
      setPasswordError('Mật khẩu xác nhận không khớp.');
      return;
    }
    setPasswordError('');
    setApiError('');
    setLoading(true);

    try {
      await axiosClient.post('/api/auth/register', {
        username: form.fullName,
        email: form.email,
        password: form.password,
      });

      setSuccess(true);
      // Brief success flash, then redirect to login
      setTimeout(() => router.push('/login'), 1500);
    } catch (err: any) {
      const msg =
        err?.response?.data?.detail ||
        err?.response?.data?.message ||
        'Đăng ký thất bại. Vui lòng thử lại.';
      setApiError(msg);
    } finally {
      setLoading(false);
    }
  };

  const EyeOpen = () => (
    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" /><circle cx="12" cy="12" r="3" />
    </svg>
  );
  const EyeOff = () => (
