  LEAD: 'Lead',
};

interface Props {
  mappings: CategoryCriteriaMappingDto[];
  categories: JobCategoryDto[];
  criteria: EvaluationCriteriaDto[];
  onRefresh: () => void;
}

interface MappingLeafNode {
  criteria: EvaluationCriteriaDto;
  mappingsByLevel: Partial<Record<SeniorityLevel, CategoryCriteriaMappingDto>>;
}

interface CategoryTreeNodeData {
  category: JobCategoryDto;
  children: CategoryTreeNodeData[];
  mappedCriteria: MappingLeafNode[];
}

interface MappingEditorState {
  mode: 'create' | 'edit';
  job_category_id: number;
  criteria_id: number;
  seniority_level: SeniorityLevel;
  weight_percentage: number;
}

interface CategoryOption {
  value: number;
  label: string;
}

const emptyEditorState: MappingEditorState = {
  mode: 'create',
  job_category_id: 0,
  criteria_id: 0,
  seniority_level: 'ALL',
  weight_percentage: 10,
};

function formatCategoryLabel(text: string | null | undefined): string {
  if (!text) return '';

  return text
    .replace(/_/g, ' ')
    .toLowerCase()
    .split(' ')
    .filter(Boolean)
    .map((word) => {
      if (word === 'qa') return 'QA';
      if (word === 'js') return 'JS';
      if (word === 'id') return 'ID';
      if (word === 'cv') return 'CV';
      if (word === 'jd') return 'JD';
      if (word === 'nestjs') return 'NestJS';
      if (word === 'mongodb') return 'MongoDB';
      if (word === 'mysql') return 'MySQL';
      if (word === 'postgresql') return 'PostgreSQL';
      if (word === 'api') return 'API';
      return word.charAt(0).toUpperCase() + word.slice(1);
    })
    .join(' ');
}

function buildCategoryTree(
  categories: JobCategoryDto[],
  criteria: EvaluationCriteriaDto[],
  mappings: CategoryCriteriaMappingDto[]
): CategoryTreeNodeData[] {
  const categoryNodes = new Map<number, CategoryTreeNodeData>();
  const criteriaById = new Map(criteria.map((item) => [item.id, item]));

  categories.forEach((category) => {
    categoryNodes.set(category.id, {
      category,
      children: [],
      mappedCriteria: [],
    });
  });

  const roots: CategoryTreeNodeData[] = [];

  categories.forEach((category) => {
    const node = categoryNodes.get(category.id);
    if (!node) return;

    if (category.parent_id && categoryNodes.has(category.parent_id)) {
      categoryNodes.get(category.parent_id)!.children.push(node);
    } else {
      roots.push(node);
    }
  });

  const mappedCriteriaByCategory = new Map<number, Map<number, MappingLeafNode>>();

  mappings.forEach((mapping) => {
    const categoryNode = categoryNodes.get(mapping.job_category_id);
    const criteriaItem = criteriaById.get(mapping.criteria_id);
    if (!categoryNode || !criteriaItem) return;

    let categoryMap = mappedCriteriaByCategory.get(mapping.job_category_id);
    if (!categoryMap) {
      categoryMap = new Map();
      mappedCriteriaByCategory.set(mapping.job_category_id, categoryMap);
    }

    let leafNode = categoryMap.get(mapping.criteria_id);
    if (!leafNode) {
      leafNode = {
        criteria: criteriaItem,
        mappingsByLevel: {},
      };
      categoryMap.set(mapping.criteria_id, leafNode);
    }

    leafNode.mappingsByLevel[mapping.seniority_level as SeniorityLevel] = mapping;
  });

  const sortTree = (nodes: CategoryTreeNodeData[]) => {
    nodes.sort((left, right) => formatCategoryLabel(left.category.name).localeCompare(formatCategoryLabel(right.category.name)));
    nodes.forEach((node) => {
      node.children.sort((left, right) => formatCategoryLabel(left.category.name).localeCompare(formatCategoryLabel(right.category.name)));
      node.mappedCriteria = Array.from(mappedCriteriaByCategory.get(node.category.id)?.values() ?? [])
        .sort((left, right) => left.criteria.criteria_name.localeCompare(right.criteria.criteria_name));
      sortTree(node.children);
    });
  };

  sortTree(roots);
  return roots;
}

function collectCategoryOptions(nodes: CategoryTreeNodeData[], parentPath: string[] = []): CategoryOption[] {
  const options: CategoryOption[] = [];

  nodes.forEach((node) => {
    const nextPath = [...parentPath, formatCategoryLabel(node.category.name)];
    options.push({
      value: node.category.id,
      label: nextPath.join(' / '),
    });
    options.push(...collectCategoryOptions(node.children, nextPath));
  });

  return options;
}

function findMappingForLevel(
  mappings: CategoryCriteriaMappingDto[],
  jobCategoryId: number,
  criteriaId: number,
  seniorityLevel: SeniorityLevel
) {
  return mappings.find(
    (mapping) =>
      mapping.job_category_id === jobCategoryId &&
      mapping.criteria_id === criteriaId &&
      mapping.seniority_level === seniorityLevel
  ) ?? null;
}

function LevelTabs({
  value,
  onChange,
}: {
  value: SeniorityLevel;
  onChange: (nextValue: SeniorityLevel) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-4 bg-slate-950/60 p-1.5 rounded-2xl border border-slate-800">
      {SENIORITY_LEVELS.map((level) => {
        const isActive = value === level;
        return (
          <button
            key={level}
            type="button"
            onClick={() => onChange(level)}
            className={`min-h-[36px] min-w-[64px] px-4 py-1.5 text-xs font-bold tracking-wide rounded-xl transition-all duration-200 select-none focus:outline-none focus:ring-1 focus:ring-teal-400/30 ${
              isActive
                ? 'bg-teal-500 text-slate-950 shadow-[0_4px_12px_rgba(20,184,166,0.25)]'
                : 'text-slate-400 hover:bg-white/[0.04] hover:text-white'
            }`}
          >
            {SENIORITY_LABELS[level]}
          </button>
        );
      })}
    </div>
  );
}

interface CriteriaBadgePopoverProps {
  criteriaCount: number;
  mappedCriteria: MappingLeafNode[];
}

function CriteriaBadgePopover({ criteriaCount, mappedCriteria }: CriteriaBadgePopoverProps) {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isOpen) return;

    const handleOutsideClick = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('click', handleOutsideClick);
    return () => {
      document.removeEventListener('click', handleOutsideClick);
    };
  }, [isOpen]);

  const togglePopover = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    setIsOpen((prev) => !prev);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.stopPropagation();
      e.preventDefault();
      setIsOpen((prev) => !prev);
    }
  };

  return (
    <div className="relative inline-block text-left" ref={containerRef}>
      <span
        role="button"
        tabIndex={0}
        onClick={togglePopover}
        onKeyDown={handleKeyDown}
        className={`rounded-full border px-1.5 py-0.5 text-[9px] font-medium uppercase tracking-[0.1em] cursor-pointer select-none transition-all duration-200 focus:outline-none ${
          isOpen
            ? 'border-teal-400 bg-teal-950/40 text-teal-300 ring-1 ring-teal-400/20'
            : 'border-slate-800 bg-slate-950/40 text-slate-500 hover:border-teal-500/50 hover:bg-teal-950/30 hover:text-teal-300 focus:border-teal-500/50 focus:bg-teal-950/30 focus:text-teal-300'
        }`}
      >
        {criteriaCount} criteria
      </span>

      {isOpen && (
        <div
          onClick={(e) => e.stopPropagation()}
          className="absolute left-0 mt-2.5 w-64 origin-top-left rounded-xl border border-slate-700/80 bg-slate-900 px-4 py-3.5 shadow-2xl shadow-black/85 z-50 animate-in fade-in slide-in-from-top-1 duration-150"
        >
          <div className="flex items-center justify-between border-b border-slate-800 pb-2 mb-2">
            <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400">
              Criteria ({criteriaCount})
            </span>
          </div>

          {mappedCriteria.length === 0 ? (
            <div className="text-xs italic text-slate-500 py-1">
              Chưa có tiêu chí nào.
            </div>
          ) : (
            <div className="max-h-48 overflow-y-auto space-y-1.5 pr-1 scrollbar-thin">
              {mappedCriteria.map((leaf) => (
                <div
                  key={leaf.criteria.id}
                  className="flex items-start gap-2 py-0.5 text-xs text-slate-200 hover:text-white transition-colors"
                >
                  <span className="text-teal-400/80 select-none">•</span>
                  <span className="font-medium truncate" title={leaf.criteria.criteria_name}>
                    {leaf.criteria.criteria_name}
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function CategoryTreeNode({
  node,
  depth,
  selectedLevel,
  expandedIds,
  onToggle,
  onEditLeaf,
  onDeleteLeaf,
}: {
  node: CategoryTreeNodeData;
  depth: number;
  selectedLevel: SeniorityLevel;
  expandedIds: Set<number>;
  onToggle: (categoryId: number) => void;
  onEditLeaf: (categoryId: number, criteriaId: number, seniorityLevel: SeniorityLevel, e?: React.MouseEvent) => void;
  onDeleteLeaf: (categoryId: number, criteriaId: number, seniorityLevel: SeniorityLevel) => void;
}) {
  const isExpanded = expandedIds.has(node.category.id);
  const selectedLeaves = node.mappedCriteria;

  // Merge children categories and criteria leaf rows for proper vertical guide line calculations
  const childrenItems = useMemo(() => {
    return [
      ...node.children.map((c) => ({ type: 'category' as const, id: `cat-${c.category.id}`, data: c })),
      ...selectedLeaves.map((l) => ({ type: 'criteria' as const, id: `crit-${l.criteria.id}`, data: l })),
    ];
  }, [node.children, selectedLeaves]);

  const hasChildren = childrenItems.length > 0;
  const isTopLevel = depth === 0;

  const folderRowClass = isTopLevel
    ? "group flex w-full cursor-pointer items-center justify-between rounded-2xl border border-slate-700/70 bg-white/[0.025] px-4 py-4 text-left transition-all hover:border-slate-500/70 hover:bg-white/[0.04] focus:outline-none focus:ring-2 focus:ring-teal-500/20"
    : "group flex w-full cursor-pointer items-center justify-between rounded-lg bg-transparent px-3 py-2 text-left transition-all hover:bg-slate-800/40 focus:outline-none focus:ring-1 focus:ring-teal-500/30";

  return (
    <div className="relative">
      <div
        role="button"
        tabIndex={0}
        onClick={() => onToggle(node.category.id)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            onToggle(node.category.id);
          }
        }}
        className={folderRowClass}
      >
        <div className="flex min-w-0 items-center gap-3">
          {isTopLevel ? (
            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl border border-teal-400/20 bg-gradient-to-br from-teal-500/15 to-cyan-500/10 text-teal-200 shadow-[0_0_0_1px_rgba(20,184,166,0.08)]">
              <Folder size={18} />
            </div>
          ) : (
            <Folder size={15} className="text-slate-400 shrink-0" />
          )}
          <div className="min-w-0">
            <div className="flex flex-wrap items-center gap-2">
              <span className={`truncate text-sm font-semibold tracking-wide ${isTopLevel ? 'text-white text-base font-bold' : 'text-slate-300'}`}>
                {formatCategoryLabel(node.category.name)}
              </span>
              <span className="rounded-md border border-slate-800 bg-slate-900/80 px-2 py-0.5 text-[9px] font-semibold uppercase tracking-[0.1em] text-slate-400">
                {node.children.length} child{node.children.length === 1 ? '' : 'ren'}
              </span>
              {selectedLeaves.length > 0 && (
                <CriteriaBadgePopover
                  criteriaCount={selectedLeaves.length}
                  mappedCriteria={selectedLeaves}
                />
              )}
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2 text-slate-300 transition-colors group-hover:text-white">
          {node.children.length > 0 && (
            <svg
              width="14"
              height="14"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2.5"
              className={`transition-transform duration-200 ${isExpanded ? 'rotate-90 text-teal-400' : 'rotate-0'}`}
            >
              <path d="m9 18 6-6-6-6" />
            </svg>
          )}
        </div>
      </div>

      {isExpanded && hasChildren && (
        <div className="mt-2 space-y-1 relative" style={{ marginLeft: '24px', paddingLeft: 0 }}>
          {childrenItems.map((item, index) => {
            const isLast = index === childrenItems.length - 1;
            const itemMidHeight = item.type === 'category' ? (isTopLevel ? 28 : 20) : 22; // adjusted vertical branch segment anchor

            return (
              <div key={item.id} className="relative">
                {/* Vertical connecting line segment */}
                <div
                  className="absolute bg-slate-700/50"
                  style={{
                    position: 'absolute',
                    left: '-20px',
                    width: '1px',
                    backgroundColor: 'rgba(51, 65, 85, 0.5)',
                    top: '-8px',
                    bottom: isLast ? `calc(100% - ${itemMidHeight}px)` : '-8px',
                  }}
                />
                {/* Horizontal branch line pointing to child icon */}
                <div 
                  className="absolute bg-slate-700/50"
                  style={{
                    position: 'absolute',
                    left: '-20px',
                    height: '1px',
                    backgroundColor: 'rgba(51, 65, 85, 0.5)',
                    top: `${itemMidHeight}px`,
                    width: '20px',
                  }}
                />

                <div style={{ paddingLeft: '24px' }}>
                  {item.type === 'category' ? (
                    <CategoryTreeNode
                      node={item.data as CategoryTreeNodeData}
                      depth={depth + 1}
                      selectedLevel={selectedLevel}
                      expandedIds={expandedIds}
                      onToggle={onToggle}
                      onEditLeaf={onEditLeaf}
                      onDeleteLeaf={onDeleteLeaf}
                    />
                  ) : (() => {
                    const leaf = item.data as MappingLeafNode;
                    const selectedMapping = leaf.mappingsByLevel[selectedLevel] ?? null;
                    const isSet = Boolean(selectedMapping);
                    const mappingWeight = selectedMapping?.weight_percentage ?? 0;

                    return (
                      <div className="group flex items-center justify-between gap-4 rounded-lg bg-transparent px-3 py-2 transition-all hover:bg-slate-800/40">
                        <div className="min-w-0 flex-1">
                          <div className="flex flex-wrap items-center gap-2">
                            <FileText size={15} className="text-emerald-400 shrink-0 shadow-[0_0_8px_rgba(52,211,153,0.15)]" />
                            <p className="text-sm font-semibold text-white tracking-wide">{leaf.criteria.criteria_name}</p>
                            <span className={`rounded-full border px-1.5 py-0.5 text-[8px] font-bold uppercase tracking-[0.1em] ${
                              isSet
                                ? 'border-teal-400/20 bg-teal-500/10 text-teal-300'
                                : 'border-slate-800 bg-slate-900/50 text-slate-500'
                            }`}>
                              {SENIORITY_LABELS[selectedLevel]}
                            </span>
                          </div>
                          <p className="mt-0.5 pl-6 text-xs text-slate-400">
                            {isSet ? `Trọng số active: ${mappingWeight}%` : 'Không có cấu hình trọng số cho cấp bậc này.'}
                          </p>
                        </div>

                        <div className="flex items-center gap-4 shrink-0">
                          <div className="min-w-[60px] text-right">
                            <p className={`text-sm font-bold font-mono tabular-nums tracking-tight ${isSet ? 'text-teal-400' : 'text-slate-500'}`}>
                              {isSet ? `${mappingWeight}%` : '0%'}
                            </p>
                          </div>

                          {/* Action buttons wrapper hidden until row hover */}
                          <div className="flex items-center gap-1.5 opacity-0 group-hover:opacity-100 transition-opacity duration-150">
                            <ActionIconButton
                              label={isSet ? 'Sửa trọng số' : 'Thêm trọng số'}
                              variant="accent"
                              onClick={(e) => onEditLeaf(node.category.id, leaf.criteria.id, selectedLevel, e)}
                              icon={(
                                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                  <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" />
                                  <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" />
                                </svg>
                              )}
                            />
                            <ActionIconButton
                              label="Xóa mapping"
                              variant="danger"
                              disabled={!selectedMapping}
                              onClick={(e) => {
                                e.stopPropagation();
                                e.preventDefault();
                                onDeleteLeaf(node.category.id, leaf.criteria.id, selectedLevel);
                              }}
                              icon={(
                                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                  <polyline points="3 6 5 6 21 6" />
                                  <path d="M19 6l-1 14H6L5 6" />
                                  <path d="M10 11v6M14 11v6" />
                                  <path d="M9 6V4h6v2" />
                                </svg>
                              )}
                            />
                          </div>
                        </div>
                      </div>
                    );
                  })()}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function MappingEditorModal({
  open,
  draft,
  saving,
  categories,
  criteria,
  selectedLevel,
  onClose,
  onSave,
  onChange,
  categoryOptions,
}: {
  open: boolean;
  draft: MappingEditorState;
  saving: boolean;
  categories: JobCategoryDto[];
  criteria: EvaluationCriteriaDto[];
  selectedLevel: SeniorityLevel;
  onClose: () => void;
  onSave: () => void;
  onChange: (nextDraft: MappingEditorState) => void;
  categoryOptions: CategoryOption[];
}) {
  const selectedCategoryLabel = categoryOptions.find((option) => option.value === draft.job_category_id)?.label ?? 'Select category';
  const selectedCriteriaLabel = criteria.find((item) => item.id === draft.criteria_id)?.criteria_name ?? 'Select criteria';

  const selectStyle = {
    backgroundImage: `url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' fill='none' viewBox='0 0 20 20'%3E%3Cpath stroke='%2394a3b8' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.5' d='m6 8 4 4 4-4'/%3E%3C/svg%3E")`,
    backgroundPosition: 'right 0.75rem center',
    backgroundSize: '1.25rem auto',
    backgroundRepeat: 'no-repeat',
    paddingRight: '2.5rem',
  };

  return (
    <Modal open={open} onClose={onClose} title={draft.mode === 'edit' ? 'Sửa trọng số' : 'Thêm mapping'} size="md">
      <div className="space-y-5">
        {draft.mode === 'create' ? (
          <div className="grid grid-cols-1 gap-4">
