export function MatchingResultPanel({
  assessment, roleTitle, analyzing, generating,
  rawCvText, rawJdText, cvDisplayName, jdDisplayName, keywordMetadata,
  criteriaFilter, activeView, onCriteriaFilter, onActiveView,
  onRefreshAssessment, onReset, onContinue,
}: Props) {
  const derivedKeywords = extractKeywordsFromEvaluation(
    assessment.evidenceItems || [],
    assessment.additionalEvidenceItems || [],
  );
  const keywords = keywordMetadata ?? { matching_skills: derivedKeywords.matchingSkills, variation_skills: derivedKeywords.variationSkills, missing_skills: derivedKeywords.missingSkills };

  const getSectionName = useCallback((key: string) => {
    const names: Record<string, string> = {
      cs_fundamentals: 'Kiến thức Khoa học Máy tính cốt lõi',
      tech_stack_alignment: 'Mức độ tương thích Tech Stack',
      project_technical_depth: 'Chiều sâu kỹ thuật trong các dự án',
      engineering_practices: 'Quy trình và Thực hành Kỹ nghệ',
      experience_evaluation: 'Đánh giá kinh nghiệm làm việc',
      education_and_certifications: 'Đánh giá học vấn & chứng chỉ',
    };
    return names[key] || key.replace(/_/g, ' ').toUpperCase();
  }, []);

  const filteredEvidence = assessment.evidenceItems?.filter((i: any) =>
    criteriaFilter === 'all' || i.status === criteriaFilter
  ) || [];
  const filteredAdditional = assessment.additionalEvidenceItems?.filter((i: any) =>
    criteriaFilter === 'all' || i.status === criteriaFilter
  ) || [];

  return (
    <div className="space-y-6">
      {}
      <div className="flex flex-wrap items-center justify-between gap-4 border-b border-border pb-4">
        <div>
          <h2 className="text-2xl font-extrabold text-foreground">Kết quả phân tích độ tương thích</h2>
          <p className="mt-0.5 text-sm text-muted-foreground">
            Dành cho vị trí <strong>{roleTitle}</strong>
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <Badge variant="secondary" className="gap-1.5">
            <span className={`size-2 rounded-full ${assessment.cached ? 'bg-emerald-500' : 'bg-amber-500'}`} />
            {assessment.cached ? 'Kết quả từ Cache' : 'Phân tích mới'}
          </Badge>
          {assessment.cached && (
            <Button size="sm" variant="outline" onClick={onRefreshAssessment}
              className="border-brand-orange text-brand-orange hover:bg-brand-orange/5">
              <RefreshCw size={12} className="mr-1.5" /> Đánh giá lại
            </Button>
          )}
        </div>
      </div>

      {}
      {(rawCvText || rawJdText) && (
        <div className="flex justify-center">
          <div className="inline-flex rounded-xl bg-muted p-1 gap-1">
            {(['ai-cards', 'visual-match'] as ActiveView[]).map((v) => (
              <button key={v} type="button" onClick={() => onActiveView(v)}
                className={`rounded-lg px-4 py-2 text-sm font-semibold transition-all ${activeView === v ? 'bg-card text-foreground shadow' : 'text-muted-foreground hover:text-foreground'}`}
              >
                {v === 'ai-cards' ? '🤖 AI Analysis Cards' : '🔍 Visual Skill Match'}
              </button>
            ))}
          </div>
        </div>
      )}

      {}
      {activeView === 'ai-cards' && (
        <div className="space-y-8">
          {}
          <div className="flex flex-wrap justify-center gap-12">
            <ScoreRing score={assessment.competencyFitScore} label="Competency Fit Score" color="#ea580c" />
            <ScoreRing score={assessment.technicalDepthScore} label="Technical Depth Score" color="#7c3aed" />
          </div>

          {}
          <div className="flex flex-wrap justify-center gap-2">
            {[
              { label: 'Role', value: getDisplayRoleTitle(assessment.roleTypeDetected) },
              { label: 'Level', value: assessment.candidateLevel },
              { label: 'YoE',  value: assessment.yearsOfExperienceEstimate },
              { label: 'Match', value: assessment.matchLevel },
            ].filter((b) => b.value).map((b) => (
              <Badge key={b.label} variant="secondary" className="text-xs">
                <span className="font-normal text-muted-foreground mr-1">{b.label}:</span>
                {b.value}
              </Badge>
            ))}
          </div>

          {}
          {assessment.eligibility?.gate_checks?.length > 0 && (
            <div className="rounded-xl border border-border bg-card p-5">
              <h3 className="mb-3 text-sm font-bold uppercase tracking-wide text-muted-foreground">Kiểm tra điều kiện</h3>
              <div className="space-y-2">
                {assessment.eligibility.gate_checks.map((check: any, i: number) => (
                  <div key={i} className="flex items-center gap-2 text-sm">
                    {check.passed
                      ? <CheckCircle size={14} className="text-emerald-500 shrink-0" />
                      : <XCircle size={14} className="text-red-500 shrink-0" />}
                    <span>{check.description || check.criterion}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {}
          <div>
            <div className="mb-4 flex items-center justify-between">
              <h3 className="font-bold text-foreground">Ma trận kỹ năng (Criteria Alignment)</h3>
              <div className="flex gap-1">
                {(['all', 'matched', 'weak', 'missing'] as CriteriaFilter[]).map((f) => (
                  <button key={f} type="button" onClick={() => onCriteriaFilter(f)}
                    className={`rounded-lg px-2.5 py-1 text-xs font-semibold capitalize transition-colors ${criteriaFilter === f ? 'bg-brand-orange text-white' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}
                  >
                    {f === 'all' ? 'Tất cả' : f}
                  </button>
                ))}
              </div>
            </div>

            {filteredEvidence.length > 0 && (
              <div className="mb-6">
                <p className="mb-3 text-xs font-bold uppercase tracking-wide text-muted-foreground">Must Have</p>
                <div className="space-y-2">{filteredEvidence.map((item: any, i: number) => <CriterionItem key={i} item={item} />)}</div>
              </div>
            )}
            {filteredAdditional.length > 0 && (
              <div>
                <p className="mb-3 text-xs font-bold uppercase tracking-wide text-muted-foreground">Prefer to Have</p>
                <div className="space-y-2">{filteredAdditional.map((item: any, i: number) => <CriterionItem key={i} item={item} />)}</div>
              </div>
            )}
          </div>

          {}
          {assessment.sectionWiseFeedback && Object.keys(assessment.sectionWiseFeedback).length > 0 && (
            <div className="rounded-xl border border-border bg-card p-5">
              <h3 className="mb-4 font-bold text-foreground">Phân tích từng phần</h3>
              <div className="space-y-4">
                {Object.entries(assessment.sectionWiseFeedback).map(([key, val]) => (
                  <div key={key}>
                    <p className="mb-1 text-xs font-bold uppercase tracking-wide text-muted-foreground">{getSectionName(key)}</p>
                    <p className="text-sm leading-relaxed text-foreground/80">{typeof val === 'object' ? JSON.stringify(val) : String(val || '')}</p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Actionable Suggestions */}
          {((assessment.topPriorityImprovements?.length ?? 0) > 0 || (assessment.actionableImprovementSuggestions?.length ?? 0) > 0) && (
            <div className="rounded-xl border border-brand-orange/20 bg-brand-orange/5 p-5">
              <h3 className="mb-4 font-bold text-foreground">Gợi ý cải thiện ưu tiên</h3>
              <div className="space-y-3">
                {((assessment.topPriorityImprovements?.length ?? 0) > 0
                  ? assessment.topPriorityImprovements!
                  : assessment.actionableImprovementSuggestions || []
                ).slice(0, 5).map((item: any, i: number) => (
                  <div key={i} className="flex items-start gap-3 text-sm">
                    <span className="flex size-5 shrink-0 items-center justify-center rounded-full bg-brand-orange text-xs font-bold text-white">{i + 1}</span>
                    <p className="text-foreground/80">{typeof item === 'string' ? item : item.suggestion || item.description || JSON.stringify(item)}</p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {}
      {activeView === 'visual-match' && rawCvText && rawJdText && (
        <div className="space-y-6">
          {}
          <div className="flex flex-wrap items-center gap-3">
            {keywords.matching_skills?.slice(0, 8).map((s: string) => (
              <span key={s} className="rounded-full bg-emerald-100 px-2.5 py-0.5 text-xs font-semibold text-emerald-700">{s}</span>
            ))}
            {keywords.missing_skills?.slice(0, 5).map((s: string) => (
              <span key={s} className="rounded-full bg-red-100 px-2.5 py-0.5 text-xs font-semibold text-red-700">{s}</span>
            ))}
          </div>
          <div className="grid gap-4 lg:grid-cols-2">
            <div className="rounded-xl border border-border bg-card p-4">
              <p className="mb-3 text-xs font-bold uppercase tracking-wide text-muted-foreground">{cvDisplayName}</p>
              <div className="max-h-[500px] overflow-y-auto text-xs leading-relaxed">
                <HighlightedText
                  text={rawCvText}
                  matches={keywords.matching_skills || []}
                  variations={keywords.variation_skills || keywords.variationSkills || []}
                  missing={keywords.missing_skills || []}
                />
              </div>
            </div>
            <div className="rounded-xl border border-border bg-card p-4">
              <p className="mb-3 text-xs font-bold uppercase tracking-wide text-muted-foreground">{jdDisplayName}</p>
              <div className="max-h-[500px] overflow-y-auto text-xs leading-relaxed">
                <HighlightedText
                  text={rawJdText}
                  matches={keywords.matching_skills || []}
                  variations={keywords.variation_skills || keywords.variationSkills || []}
                  missing={keywords.missing_skills || []}
                />
              </div>
            </div>
          </div>
        </div>
      )}

      {}
      <div className="flex flex-wrap items-center justify-between gap-3 border-t border-border pt-4">
        <Button variant="outline" onClick={onReset}>Tải lại tài liệu khác</Button>
        <Button
          onClick={onContinue}
          disabled={generating}
          className="bg-brand-orange text-white hover:bg-brand-orange-hover"
        >
          {generating ? 'Đang tạo ngân hàng câu hỏi...' : 'Bắt đầu Phỏng vấn →'}
        </Button>
      </div>
    </div>
  );
}

'use client';

import type { DragEvent, ChangeEvent, RefObject } from 'react';
import { Briefcase, FileText, FolderOpen, AlertTriangle, Eye, X as XIcon } from 'lucide-react';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Button, buttonVariants } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import Link from 'next/link';
import type { CvSource, JdSource } from '@/hooks/useNewInterview';
import { cn } from '@/lib/utils';

interface ComboboxOption { id: number; label: string; date: string; }


import { useState, useRef, useEffect } from 'react';
import { ChevronDown, Search, X } from 'lucide-react';

interface ComboboxProps {
  options: ComboboxOption[];
  selectedId: number | null;
  onSelect: (id: number | null) => void;
  placeholder: string;
  searchPlaceholder: string;
  icon: React.ReactNode;
}

function Combobox({ options, selectedId, onSelect, placeholder, searchPlaceholder, icon }: ComboboxProps) {
  const [open, setOpen]   = useState(false);
  const [q,    setQ]      = useState('');
  const wrapRef           = useRef<HTMLDivElement>(null);
  const selected          = options.find((o) => o.id === selectedId);
  const filtered          = options.filter((o) => o.label.toLowerCase().includes(q.toLowerCase()));

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  return (
    <div ref={wrapRef} className="relative w-full">
      <button
        type="button"
        onClick={() => setOpen(!open)}
        className={`flex w-full items-center justify-between rounded-lg border px-3 py-2.5 text-sm transition-all ${open ? 'border-brand-orange shadow-[0_0_0_3px_rgba(234,88,12,0.12)]' : 'border-border'} bg-card`}
      >
        <span className="flex min-w-0 items-center gap-2">
          {icon}
          <span className={`truncate ${selected ? 'font-medium text-foreground' : 'text-muted-foreground'}`}>
            {selected ? selected.label : placeholder}
          </span>
        </span>
        <span className="flex shrink-0 items-center gap-1">
          {selected && (
            <span onClick={(e) => { e.stopPropagation(); onSelect(null); }} className="rounded-full p-0.5 text-muted-foreground hover:text-destructive">
              <X size={12} />
            </span>
          )}
          <ChevronDown size={14} className={`text-muted-foreground transition-transform ${open ? 'rotate-180' : ''}`} />
        </span>
      </button>

      {open && (
        <div className="absolute left-0 right-0 top-[calc(100%+4px)] z-50 rounded-lg border border-border bg-card p-2 shadow-lg">
          <div className="mb-2 flex items-center gap-2 rounded-md border border-border bg-muted/50 px-2 py-1.5">
            <Search size={13} className="text-muted-foreground" />
            <input
              value={q} onChange={(e) => setQ(e.target.value)}
              placeholder={searchPlaceholder}
              className="w-full bg-transparent text-xs outline-none text-foreground placeholder:text-muted-foreground"
            />
          </div>
          <div className="max-h-52 overflow-y-auto flex flex-col gap-0.5">
            {filtered.length === 0 ? (
              <p className="py-4 text-center text-xs text-muted-foreground">Không tìm thấy kết quả</p>
            ) : filtered.map((opt) => {
              const isSelected = opt.id === selectedId;
              return (
                <button key={opt.id} type="button"
                  onClick={() => { onSelect(opt.id); setOpen(false); setQ(''); }}
                  className={`flex w-full items-center justify-between rounded-md px-2.5 py-2 text-left text-xs transition-colors ${isSelected ? 'bg-accent text-brand-orange font-semibold' : 'text-foreground hover:bg-muted'}`}
                >
                  <span className="truncate max-w-[75%]" title={opt.label}>{opt.label}</span>
                  <span className="text-muted-foreground">{opt.date}</span>
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

// ── File Drop Zone ─────────────────────────────────────────────────────────────
interface DropZoneProps {
  zone: 'cv' | 'jd';
  file: File | null;
  dragActive: boolean;
  error: string | null;
  accept: string;
  hint: string;
  icon: React.ReactNode;
  inputRef: RefObject<HTMLInputElement | null>;
  onDragOver: (e: DragEvent<HTMLDivElement>, zone: 'cv' | 'jd') => void;
  onDragLeave: (zone: 'cv' | 'jd') => void;
  onDrop: (e: DragEvent<HTMLDivElement>, zone: 'cv' | 'jd') => void;
  onFileChange: (e: ChangeEvent<HTMLInputElement>, zone: 'cv' | 'jd') => void;
  onClear: () => void;
  onTrigger: () => void;
}

function DropZone({ zone, file, dragActive, error, accept, hint, icon, inputRef, onDragOver, onDragLeave, onDrop, onFileChange, onClear, onTrigger }: DropZoneProps) {
  if (file) {
    return (
      <div className="flex items-center justify-between rounded-xl border border-brand-orange/30 bg-brand-orange/5 p-3.5">
        <div className="flex items-center gap-3">
          <FileText size={22} className="text-brand-orange shrink-0" />
          <div>
            <p className="text-sm font-medium text-foreground">{file.name}</p>
            <p className="text-xs text-muted-foreground">{(file.size / 1024 / 1024).toFixed(2)} MB</p>
          </div>
        </div>
        <button onClick={onClear} className="rounded-full p-1 text-muted-foreground hover:text-destructive hover:bg-destructive/10 transition-colors">
          <XIcon size={14} />
        </button>
      </div>
    );
  }

  return (
    <div
      className={`flex cursor-pointer flex-col items-center justify-center gap-2 rounded-xl border-2 border-dashed p-8 text-center transition-colors ${dragActive ? 'border-brand-orange bg-brand-orange/8' : 'border-border hover:border-brand-orange/50 hover:bg-accent/50'}`}
      onDragOver={(e) => onDragOver(e, zone)}
      onDragLeave={() => onDragLeave(zone)}
      onDrop={(e) => onDrop(e, zone)}
      onClick={onTrigger}
    >
      <span className="text-muted-foreground/50">{icon}</span>
      <p className="text-sm text-muted-foreground">
        Kéo thả hoặc <span className="font-semibold text-brand-orange">chọn tệp</span>
      </p>
      <p className="text-xs text-muted-foreground/70">{hint}</p>
      <input ref={inputRef} type="file" className="hidden" accept={accept} onChange={(e) => onFileChange(e, zone)} />
    </div>
  );
}

// ── Props ──────────────────────────────────────────────────────────────────────
interface UploadStepProps {
  cvSource: CvSource; setCvSource: (v: CvSource) => void;
  jdSource: JdSource; setJdSource: (v: JdSource) => void;
  cvFile: File | null; jdFile: File | null;
  jdText: string; setJdText: (v: string) => void;
  dragOverCv: boolean; dragOverJd: boolean;
  cvError: string | null; jdError: string | null;
  savedResumes: any[]; savedJds: any[];
  selectedResumeId: number | null; setSelectedResumeId: (id: number | null) => void;
  selectedJdId: number | null; setSelectedJdId: (id: number | null) => void;
  fileInputCvRef: RefObject<HTMLInputElement | null>;
  fileInputJdRef: RefObject<HTMLInputElement | null>;

  defaultResumeId: string | null;
  onDragOver: (e: DragEvent<HTMLDivElement>, zone: 'cv' | 'jd') => void;
  onDragLeave: (zone: 'cv' | 'jd') => void;
  onDrop: (e: DragEvent<HTMLDivElement>, zone: 'cv' | 'jd') => void;
  onFileChange: (e: ChangeEvent<HTMLInputElement>, zone: 'cv' | 'jd') => void;
  onTrigger: (zone: 'cv' | 'jd') => void;
  onClearCv: () => void;
  onClearJd: () => void;
  onViewPdf: (url: string, title: string) => void;
  onSubmit: () => void;
  disabled: boolean;
}

// ── Main Export ────────────────────────────────────────────────────────────────
export function UploadStep({
  cvSource, setCvSource, jdSource, setJdSource,
  cvFile, jdFile, jdText, setJdText,
  dragOverCv, dragOverJd, cvError, jdError,
  savedResumes, savedJds,
  selectedResumeId, setSelectedResumeId,
  selectedJdId, setSelectedJdId,
  fileInputCvRef, fileInputJdRef,
  defaultResumeId,
  onDragOver, onDragLeave, onDrop, onFileChange, onTrigger,
  onClearCv, onClearJd, onViewPdf,
  onSubmit, disabled,
}: UploadStepProps) {
  return (
    <div className="space-y-6">
      <div className="grid gap-6 md:grid-cols-2">
        {/* ── CV Column ── */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-foreground">Hồ sơ cá nhân (CV)</label>
          <div className="flex gap-1.5">
            {(['upload', 'saved', ...(defaultResumeId ? ['default'] : [])] as CvSource[]).map((src) => (
              <button key={src} type="button"
                onClick={() => setCvSource(src)}
                className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${cvSource === src ? 'bg-brand-orange text-white' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}
              >
                {src === 'upload' ? 'Tải CV mới' : src === 'saved' ? 'CV đã lưu' : 'CV mặc định'}
              </button>
            ))}
          </div>

          {cvSource === 'upload' && (
            <DropZone zone="cv" file={cvFile} dragActive={dragOverCv} error={cvError}
              accept=".pdf" hint="PDF • Tối đa 10MB"
              icon={<FolderOpen size={36} />}
              inputRef={fileInputCvRef}
              onDragOver={onDragOver} onDragLeave={onDragLeave} onDrop={onDrop}
              onFileChange={onFileChange} onClear={onClearCv} onTrigger={() => onTrigger('cv')}
            />
          )}

          {cvSource === 'saved' && (
            <Combobox
              options={savedResumes.map((r) => ({ id: r.id, label: r.file_name, date: new Date(r.created_at).toLocaleDateString('vi-VN') }))}
              selectedId={selectedResumeId} onSelect={setSelectedResumeId}
              placeholder="-- Chọn CV trong danh sách --"
              searchPlaceholder="Tìm kiếm CV theo tên..."
              icon={<FileText size={15} className="text-brand-orange shrink-0" />}
            />
          )}

          {cvSource === 'default' && (() => {
            const def = savedResumes.find((r) => String(r.id) === String(defaultResumeId));
            return (
              <div className="space-y-2">
                <div className="flex items-center gap-3 rounded-xl border border-brand-orange/30 bg-brand-orange/5 p-3.5">
                  <FileText size={22} className="text-brand-orange shrink-0" />
                  <p className="text-sm font-medium text-foreground">{def?.file_name || 'Đang tải CV mặc định...'}</p>
                </div>
                {def?.file_url && (
                  <Button size="sm" variant="outline" onClick={() => onViewPdf(def.file_url, `CV mặc định: ${def.file_name}`)}>
                    <Eye size={13} className="mr-1.5" /> Xem CV mặc định
                  </Button>
                )}
              </div>
            );
          })()}

          {cvError && <p className="flex items-center gap-1 text-xs text-destructive"><AlertTriangle size={12} /> {cvError}</p>}
        </div>

        {/* ── JD Column ── */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-foreground">Mô tả công việc (JD)</label>
          <div className="flex gap-1.5">
            {(['upload', 'text', 'saved'] as JdSource[]).map((src) => (
              <button key={src} type="button"
                onClick={() => setJdSource(src)}
                className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${jdSource === src ? 'bg-brand-orange text-white' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}
              >
                {src === 'upload' ? 'Tải tệp JD' : src === 'text' ? 'Dán văn bản' : 'JD đã lưu'}
              </button>
            ))}
          </div>

          {jdSource === 'upload' && (
            <DropZone zone="jd" file={jdFile} dragActive={dragOverJd} error={jdError}
              accept=".pdf,.docx,.doc" hint="PDF, DOCX, DOC • Tối đa 10MB"
              icon={<Briefcase size={36} />}
              inputRef={fileInputJdRef}
              onDragOver={onDragOver} onDragLeave={onDragLeave} onDrop={onDrop}
              onFileChange={onFileChange} onClear={onClearJd} onTrigger={() => onTrigger('jd')}
            />
          )}

          {jdSource === 'text' && (
            <Textarea
              value={jdText} onChange={(e) => setJdText(e.target.value)}
              placeholder="Dán toàn bộ nội dung bản mô tả công việc (JD) vào đây..."
              className="min-h-[180px] resize-none"
            />
          )}

          {jdSource === 'saved' && (
            <Combobox
              options={savedJds.map((j) => ({ id: j.id, label: j.title, date: new Date(j.created_at).toLocaleDateString('vi-VN') }))}
              selectedId={selectedJdId} onSelect={setSelectedJdId}
              placeholder="-- Chọn JD trong danh sách --"
              searchPlaceholder="Tìm kiếm JD theo tên..."
              icon={<Briefcase size={15} className="text-blue-500 shrink-0" />}
            />
          )}

          {jdError && <p className="flex items-center gap-1 text-xs text-destructive"><AlertTriangle size={12} /> {jdError}</p>}
        </div>
      </div>

      {}
      <div className="flex items-center justify-end gap-3 pt-2">
        <Link href="/" className={cn(buttonVariants({ variant: 'outline' }))}>
          Hủy bỏ
        </Link>
        <Button onClick={onSubmit} disabled={disabled} className="bg-brand-orange text-white hover:bg-brand-orange-hover">
          Tải lên CV &amp; JD
        </Button>
      </div>
    </div>
  );
}

