/**
 * matchKeywords.ts
 *
 * BFF utility for Jobscan-style Visual Keyword Matching.
 *
 * Takes the original raw text of a CV and a Job Description (pre-LLM,
 * as extracted directly from the PDF), then calls the OpenRouter LLM
 * in strict JSON mode to:
 *   1. Identify all skill/keyword requirements in the JD.
 *   2. Determine which are present (matched) or absent (missing) in the CV.
 *   3. Classify each as "hard" (technical) or "soft" skill.
 *
 * Returns a KeywordMatchResult. On any LLM failure or JSON parse error
 * the function falls back gracefully to { matching_skills: [], missing_skills: [] }.
 *
 * LLM latency: ~1–3 seconds (OpenRouter / free-tier model).
 */

export interface SkillEntry {
  /** Unique visual tag ID (e.g. "ms1", "msk2") */
  id: string;
  /** The canonical keyword exactly as it appears in the JD */
  keyword: string;
  /** "hard" for technical skills, "soft" for interpersonal/behavioral skills */
  category: 'hard' | 'soft';
  /** Optional semantically equivalent variants used to scan the CV */
  variants?: string[];
}

export interface KeywordMatchResult {
  /** Keywords present in the JD that were found (or semantically matched) in the CV */
  matching_skills: SkillEntry[];
  /** Keywords present in the JD that are absent from the CV */
  missing_skills: SkillEntry[];
}

const FALLBACK: KeywordMatchResult = { matching_skills: [], missing_skills: [] };

/**
 * Extract and match skill keywords between a JD and a CV using an LLM call.
 *
 * @param rawResumeText  Pre-LLM plain text extracted from the candidate's CV/resume PDF.
 * @param rawJdText      Pre-LLM plain text extracted from the Job Description PDF/text.
 * @returns              A KeywordMatchResult categorising skills as matching or missing.
 */
export async function matchKeywords(
  rawResumeText: string,
  rawJdText: string
): Promise<KeywordMatchResult> {
  const apiKey = process.env.LLM_API_KEY;
  const apiUrl = process.env.LLM_API_URL || 'https://openrouter.ai/api/v1';
  const model = process.env.LLM_MODEL || 'poolside/laguna-xs-2.1:free';

  if (!apiKey) {
    console.error('[matchKeywords] LLM_API_KEY is not set. Returning empty result.');
    return FALLBACK;
  }

  // Truncate inputs to avoid excessive token usage (~4000 chars each is enough)
  const cvSnippet = rawResumeText.slice(0, 4000);
  const jdSnippet = rawJdText.slice(0, 4000);

  const systemPrompt = `You are a technical recruiter assistant specialised in resume screening.
Your task is to compare a Job Description (JD) against a Candidate Resume (CV) and identify skill keywords.

You MUST return a valid JSON object strictly matching this schema (no markdown, no extra keys):
{
  "matching_skills": [
    { "id": "ms1", "keyword": "string", "category": "hard" | "soft", "variants": ["string"] }
  ],
  "missing_skills": [
    { "id": "msk1", "keyword": "string", "category": "hard" | "soft" }
  ]
}

Rules:
- Extract every distinct technical skill, tool, framework, methodology, certification, and soft skill from the JD.
- For each keyword, check if it OR a close semantic variant (e.g. "ReactJS" vs "React") appears in the CV text.
- If found (even as a variant): include it in "matching_skills" with any detected variant forms in the "variants" array.
- If NOT found: include it in "missing_skills".
- Classify "hard" for technical/tool/framework/language/platform skills.
- Classify "soft" for interpersonal, communication, behavioural, or process skills.
- IDs for matching_skills: ms1, ms2, ms3 ... (sequential).
- IDs for missing_skills: msk1, msk2, msk3 ... (sequential).
- Do NOT invent keywords not present in the JD.
- Return ONLY the JSON object. No explanation, no markdown fences.`;

  const userPrompt = `### JOB DESCRIPTION ###
${jdSnippet}

### CANDIDATE RESUME ###
${cvSnippet}`;

  try {
    const response = await fetch(`${apiUrl}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model,
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt },
        ],
        // Enforce strict JSON output - avoids markdown fences and free-text responses
        response_format: { type: 'json_object' },
        temperature: 0.0,
        max_tokens: 2048,
      }),
    });

    if (!response.ok) {
      const errText = await response.text();
      console.error(`[matchKeywords] LLM API returned ${response.status}:`, errText);
      return FALLBACK;
    }

    const data = await response.json();
    const rawContent: string | undefined = data?.choices?.[0]?.message?.content;

    if (!rawContent) {
      console.error('[matchKeywords] LLM returned empty content.');
      return FALLBACK;
    }

    // Parse and validate the returned JSON
    let parsed: any;
    try {
      parsed = JSON.parse(rawContent);
    } catch (parseErr) {
      console.error('[matchKeywords] Failed to parse LLM JSON response:', parseErr, '\nRaw:', rawContent);
      return FALLBACK;
    }

    // Basic structural validation before returning
    const matchingSkills: SkillEntry[] = Array.isArray(parsed?.matching_skills)
      ? parsed.matching_skills.filter(
          (s: any) => typeof s?.id === 'string' && typeof s?.keyword === 'string'
        )
      : [];

    const missingSkills: SkillEntry[] = Array.isArray(parsed?.missing_skills)
      ? parsed.missing_skills.filter(
          (s: any) => typeof s?.id === 'string' && typeof s?.keyword === 'string'
        )
      : [];

    console.log(
      `[matchKeywords] Done. Matching: ${matchingSkills.length}, Missing: ${missingSkills.length}`
    );

    return { matching_skills: matchingSkills, missing_skills: missingSkills };
  } catch (err) {
    console.error('[matchKeywords] Unexpected error during LLM call:', err);
    return FALLBACK;
  }
}

import { useAuthStore } from '@/store/authStore';

export interface SkillEntry {
  id: string;
  keyword: string;
  category: 'hard' | 'soft';
  variants?: string[];
}

export interface KeywordMetadata {
  matching_skills: SkillEntry[];
  missing_skills: SkillEntry[];
}

export interface IngestResponse {
  sessionId: string;
  totalChunksCount: number;
  success: boolean;
  resumeId?: number;
  jdId?: number;
  /** Jobscan-style keyword match metadata from matchKeywords.ts */
  keywordMetadata?: KeywordMetadata;
  /** Pre-LLM raw text extracted from CV PDF */
  rawCvText?: string | null;
  /** Pre-LLM raw text extracted from JD PDF */
  rawJdText?: string | null;
}


export interface AssessmentResponse {
  id: string;
  sessionId: string;
  competencyFitScore: number;
  technicalDepthScore: number;
  matchLevel: string;
  candidateLevel: string;
  roleTypeDetected: string;
  yearsOfExperienceEstimate: string;
  strongAreas: string[];
  gapAreas: string[];
  criticalMissingSkills: string[];
  sectionWiseFeedback: Record<string, string>;
  actionableImprovementSuggestions: string[];
  cached: boolean;
  createdAt: string;
  evidenceItems?: any[];
  additionalEvidenceItems?: any[];
  scoreBreakdown?: any;
  topPriorityImprovements?: any[];
  eligibility?: any;
}

const getBaseUrl = () => {
  // Client-side call to Next.js API route
  return '/api/matching';
};

export const cvJdMatchingService = {
  /**
   * Ingest CV (PDF) and JD (PDF or raw text) for a given session
   */
  async ingestCvJd(
    sessionId: string,
    cvFile: File | null,
    jdFile: File | null,
    jdText: string | null,
    resumeId?: number | null,
    jdId?: number | null
  ): Promise<IngestResponse> {
    const formData = new FormData();
    if (cvFile) {
      formData.append('cvFile', cvFile);
    }
    if (jdFile) {
      formData.append('jdFile', jdFile);
    }
    if (jdText) {
      formData.append('jdText', jdText);
    }
    if (resumeId) {
      formData.append('resumeId', String(resumeId));
    }
    if (jdId) {
      formData.append('jdId', String(jdId));
    }

    const headers: Record<string, string> = {};
    const token = useAuthStore.getState().token;
    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    const res = await fetch(`${getBaseUrl()}/ingest/${sessionId}`, {
      method: 'POST',
      body: formData,
      headers: headers,
    });

    if (!res.ok) {
      throw new Error(`Ingest request failed: ${res.statusText}`);
    }

    return await res.json();
  },

  /**
   * Fetch matching assessment details
   */
  async getAssessment(
    sessionId: string,
    forceRefresh = false,
    resumeId?: number | null,
    jdId?: number | null
  ): Promise<AssessmentResponse> {
    let url = `${getBaseUrl()}/assess?sessionId=${sessionId}&forceRefresh=${forceRefresh}`;
    if (resumeId) {
      url += `&resumeId=${resumeId}`;
    }
    if (jdId) {
      url += `&jdId=${jdId}`;
    }
    
    const headers: Record<string, string> = {};
    const token = useAuthStore.getState().token;
    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    const res = await fetch(url, {
      headers: headers
    });

    if (!res.ok) {
      const errorText = await res.text();
      throw new Error(`Assessment request failed: ${res.statusText} - ${errorText}`);
    }

    return await res.json();
  }
};

/**
 * Interview Session History Service
 * 
 * Exposes an asynchronous interface to persist and retrieve interview session records.
 * Integrates with PostgreSQL database via server-side Next.js route handlers.
 */

export interface QuestionFeedback {
  question: string;
  answer: string;
  score: number;
  strengths: string;
  improvements: string;
  suggestedAnswer: string;
  topicTag: string;
  isDeepDive: boolean;
}

export interface SessionHistoryItem {
  id: string;
  date: string;
  interviewType: 'Technical' | 'Behavioural' | 'Live Coding' | 'Case Study' | 'System Design';
  roleTitle: string;
  cvFilename: string;
  jdFilename: string;
  overallScore?: number;
  status: 'Completed' | 'In progress' | 'Not started';
  questions: QuestionFeedback[];
  overallFeedback?: string;
  competencyFitScore?: number;
  skillsAnalysis?: {
    analysis?: string;
    criticalMissingSkills?: string[];
  };
  experienceEvaluation?: string;
  projectEvaluation?: string;
  technicalDepthScore?: number;
  matchLevel?: string;
  candidateLevel?: string;
  roleTypeDetected?: string;
  yearsOfExperienceEstimate?: string;
  strongAreas?: string[];
  gapAreas?: string[];
  criticalMissingSkills?: string[];
  sectionWiseFeedback?: Record<string, string>;
  actionableSuggestions?: string[];
  resumeId?: number;
  jdId?: number;
  evidenceItems?: any[];
  additionalEvidenceItems?: any[];
  scoreBreakdown?: any;
  topPriorityImprovements?: any[];
  hiringRecommendation?: string;
  eligibility?: any;
}

export interface SessionSavePayload extends SessionHistoryItem {
  replaceQuestions?: boolean;
}

export const historyService = {
  /**
   * Fetch all past practice sessions
   */
  async getHistory(): Promise<SessionHistoryItem[]> {
    try {
      const res = await fetch('/api/history');
      if (!res.ok) {
        throw new Error(`Failed to fetch history: ${res.statusText}`);
      }
      return await res.json();
    } catch (err) {
      console.error('[historyService] Error loading history, falling back to empty list:', err);
      return [];
    }
  },

  /**
   * Fetch details of a specific session by ID
   */
  async getSessionById(id: string): Promise<SessionHistoryItem | null> {
    try {
      const res = await fetch(`/api/history/${id}`);
      if (!res.ok) {
        if (res.status === 404) return null;
        throw new Error(`Failed to fetch session: ${res.statusText}`);
      }
      return await res.json();
    } catch (err) {
      console.error(`[historyService] Error loading session ${id}:`, err);
      return null;
    }
  },

  /**
   * Save or update an interview session in history
   */
  async saveSession(session: SessionSavePayload): Promise<SessionHistoryItem> {
    try {
      const res = await fetch('/api/history', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(session)
      });

      if (!res.ok) {
        throw new Error(`Failed to save session: ${res.statusText}`);
      }

      const data = await res.json();
      return data.session;
    } catch (err) {
      console.error(`[historyService] Error saving session ${session.id}:`, err);
      return session;
    }
  },

  /**
   * Create an initial blank session
   */
  async createSession(
    id: string,
    roleTitle: string,
    cvFilename: string,
    jdFilename: string,
    status: SessionHistoryItem['status'] = 'Not started'
  ): Promise<SessionHistoryItem> {
    const newSession: SessionSavePayload = {
      id,
      date: new Date().toISOString(),
      interviewType: 'Technical',
      roleTitle,
      cvFilename,
      jdFilename,
      status,
      questions: [],
      replaceQuestions: false
    };

    return this.saveSession(newSession);
  },

  /**
   * Clone a session to restart interview
   */
  async cloneSession(sessionId: string): Promise<string> {
    const res = await fetch(`/api/history/${sessionId}/clone`, {
      method: 'POST',
    });
    if (!res.ok) {
      throw new Error(`Failed to clone session: ${res.statusText}`);
    }
    const data = await res.json();
    return data.newSessionId;
  }
};
